window.V3T&&V3T.more&&V3T.more({"scene":[{"id":"tetradka","t":"Тетрадка","l":[["valerka","Баба Шура, а что вы всё пишете?"],["shura","Кто где стоял. С восемьдесят третьего."],["valerka","А зачем?"],["shura","Чтобы в восемьдесят четвёртом было с чем сравнить."]]},{"id":"metla","t":"Метла","l":[["mihalych","Кто опять на газоне стоял?"],["shura","Записано: синяя «Шестёрка», в семь сорок две."],["mihalych","Чья?"],["shura","Твоя, Михалыч."],["mihalych","…Я к ней метлу прислонял."]]},{"id":"moskvich","t":"«Москвич»","l":[["ded","Шура, я бы тоже так вывел."],["shura","Ты свой «Москвич» с девяносто восьмого выводишь."],["ded","Я жду, пока двор освободится."],["shura","(показывает на пустой двор)"],["ded","…Сегодня уже поздно."]]},{"id":"diagonal","t":"Диагональ","l":[["galya","Шура, у вас опять всё заставлено!"],["shura","Это у тебя, Галя, «Ока» поперёк."],["galya","Не поперёк. По диагонали. Это стиль."],["shura","Тогда и мой на лавочке не спит. Он медитирует."]]},{"id":"stuchit","t":"Стучит","l":[["tolik","Слышишь, стучит?"],["valerka","Слышу! Что это?"],["tolik","Это я. Ключом. Проверяю, слушаешь ли ты."]]},{"id":"ryba","t":"Рыба","l":[["mityai","Рыба!"],["shura","Митяй, ты с кем играешь? Ты же один."],["mityai","Вот поэтому и выигрываю."]]},{"id":"kot","t":"Чей кот","l":[["sansan","Чей кот на капоте моей «Волги»?!"],["shura","Ничей."],["sansan","А машина тогда чья?"],["shura","По-моему, уже его."]]},{"id":"sobranie","t":"Собрание","l":[["shura","Повестка: парковка. Кто за порядок?"],["who","(все руки вверх)"],["shura","Кто готов переставить свою машину?"],["who","(тишина)"],["shura","Единогласно. Переставляет новенький."]]},{"id":"shturman","t":"Штурман","l":[["valerka","Налево! Нет, направо!"],["shura","Валерка, где у тебя право?"],["valerka","Где рука с мороженым."],["shura","Так ты его съел."],["valerka","…Тогда прямо."]]},{"id":"sanatoriy","t":"Санаторий","l":[["galya","Шура, а где ваш водитель три дня был?"],["shura","В санатории."],["galya","В каком?"],["shura","В закрытом. Для водителей. Туда не со всякого двора берут."]]},{"id":"ochki","t":"Очки","l":[["shura","Мой, чья это синяя «Волга» у третьего подъезда?"],["ded","Шура, надень очки. Это мусорный бак."],["shura","Всё равно запиши. На чужом месте стоит."]]},{"id":"ulov","t":"Улов","l":[["petrovich","Шура, принимай: три карася к пирогам!"],["shura","Записываю. Карась, карась, карась. Где стояли?"],["petrovich","В реке."],["shura","Без разрешения. Ладно, первый раз — пирогом обойдёмся."]]},{"id":"kluyot","t":"Клюёт","l":[["petrovich","Шура, а у вас во дворе клюёт?"],["shura","У нас паркуются."],["petrovich","А разница?"],["shura","Рыба потом уплывает. А «Москвич» у моего — с девяносто восьмого."]]},{"id":"zadacha","t":"Задача","l":[["valerka","Нам задали: из пункта А в пункт Б выехала машина…"],["shura","Из нашего двора?"],["valerka","Не сказано."],["shura","Значит, не из нашего. Из нашего так просто не выезжают."]]},{"id":"pirozhki","t":"Пирожки","l":[["valya","Пирожки! С капустой, с картошкой, с мясом!"],["ded","Мне с мясом."],["valya","С мясом — тем, кто сегодня без аварий."],["ded","Я сегодня вообще не ездил."],["valya","Вот поэтому с капустой."]]},{"id":"uchastkovy","t":"Участковый","l":[["uch","Александра Петровна, всё спокойно?"],["shura","В 7:40 «Шестёрка» на газоне, в 8:15 «Ока» поперёк, в 9:02 кот на «Волге»."],["uch","Я, вообще-то, поздороваться зашёл."],["shura","Здравствуйте. В 9:15 вы встали у пожарного гидранта."]]},{"id":"shlyapka","t":"Шляпка","l":[["klava","(медленно переходит двор)"],["tolik","Клава, побыстрее можно? «Икарус» ждёт!"],["klava","Подождёт. Шляпка новая."],["shura","Не торопи, Толик. Она её с утра третий раз через двор проносит."]]},{"id":"pravila","t":"Правила","l":[["mityai","Валерка, садись в домино."],["valerka","Я правил не знаю."],["mityai","Отлично. Значит, сегодня я выиграю честно."]]},{"id":"urok","t":"Урок вождения","l":[["sansan","Руки на руль. Зеркала. Ремень. Молодец."],["valerka","Поехали?"],["sansan","Куда? Двор заставлен."],["valerka","А когда освободится?"],["ded","Я с девяносто восьмого жду, сынок."]]},{"id":"sugrob","t":"Сугроб","l":[["shura","Михалыч, а где машины?"],["mihalych","Под снегом. Я сугробы ровнял."],["shura","А «Волга» Сан Саныча?"],["mihalych","…Вон тот сугроб, повыше. С антенной."]]},{"id":"klyuch","t":"Ключ на десять","l":[["tolik","Валерка, подай ключ на десять."],["valerka","Вот."],["tolik","Это на двенадцать."],["valerka","А разница?"],["tolik","Два. Как между «починил» и «пусть пока так»."]]},{"id":"bez_avariy","t":"Без аварий","l":[["galya","Шура, у нас вчера двадцать машин вывели!"],["shura","А у нас тридцать."],["galya","А у нас — без аварий."],["shura","Галя, у вас одна «Ока». Она с восемьдесят девятого не выезжала."],["galya","Вот поэтому и без аварий."]]},{"id":"krossvord","t":"Кроссворд","l":[["zina","Шура, помоги: «Стоит поперёк двора», шесть букв."],["shura","Галина."],["zina","Не сходится."],["shura","Значит, кроссворд не про наш двор."]]},{"id":"lift","t":"Лифт","l":[["zina","А у нас в доме новый лифт поставили!"],["shura","А у нас — шлагбаум."],["zina","И как?"],["shura","Как лифт. Ездят все, а ключ у одного."]]},{"id":"barsik","t":"Барсик","l":[["tolik","Чей кот на моём «Москвиче»?"],["shura","Барсик."],["tolik","Сгони его, мне ехать."],["shura","(Барсик открывает один глаз и смотрит на Толика)"],["tolik","…Ладно. Завтра поеду."]]},{"id":"poslednee","t":"И последнее","l":[["shura","И последнее…"],["who","(все встают)"],["shura","Сядьте. «И последнее» у меня — пункт седьмой из двенадцати."]]},{"id":"znakomstvo","t":"Знакомство","l":[["shura","Мой, помнишь, где мы познакомились?"],["ded","У гаража. Ты записала мой номер."],["shura","Романтично было."],["ded","Это был штраф, Шура."]]},{"id":"navigator","t":"Навигатор","l":[["valerka","У меня навигатор! «Через сто метров поверните налево»."],["shura","Какое налево? Там клумба."],["valerka","«Маршрут перестроен»."],["shura","Вот. Со мной все так."]]},{"id":"gazon","t":"Газон","l":[["mihalych","Газон посеял! Три недели не ступать!"],["valerka","А машинам?"],["mihalych","Машинам — пять."],["shura","А тебе, Михалыч?"],["mihalych","Мне можно. Я с ним разговариваю."]]},{"id":"hleb","t":"Хлебный","l":[["valya","Хлеб привезла! Кто первый?"],["shura","Я. С семи утра стою."],["valya","Так фургон в восемь приходит."],["shura","Вот поэтому и первая."]]}],"serial":[{"id":"moskvich","t":"Кузьмич продаёт «Москвич»","ep":["Кузьмич повесил на «Москвич» табличку «Продаётся». Мой сразу пошёл смотреть. Боюсь, вернётся с «Москвичом».","Мой осматривал «Москвич» Кузьмича два часа. Сказал: «Хорошая машина, но мой лучше». Завтра пойдёт сравнивать снова.","Кузьмич назвал цену. Мой ответил: «За эти деньги мой сам уедет». Кузьмич обиделся. Ночью в гараже кто-то стучал.","Стучал Толик. Кузьмич просил: «Сделай, чтоб завёлся при покупателе». Толик: «Один раз — смогу». Покупатель — завтра.","Пришёл покупатель. Молодой, в куртке. Спросил: «А он ездит?» Кузьмич задумался. Думает до сих пор.","Покупатель думает до субботы. Кузьмич второй день моет «Москвич». Под грязью нашлась фара, о которой он не знал.","Митяй сказал, что покупатель — его внучатый племянник. Кузьмич снизил цену. Племянник об этом ещё не знает.","Толик признался: «один раз заведётся» — это он про сегодня. А покупатель придёт завтра. Кузьмич не спал.","Ночью Кузьмич с Толиком толкали «Москвич» вокруг двора — «чтобы мотор помнил». Утром Михалыч нашёл следы на газоне.","Михалыч требует с Кузьмича за газон. Кузьмич предложил расплатиться «Москвичом». Михалыч думает. Прав у него нет.","Суббота. Покупатель пришёл с отцом. Отец увидел «Москвич» и снял кепку. У нас так только перед «Победой» делают.","Отец покупателя продал этот «Москвич» Кузьмичу в восемьдесят шестом. Хочет вернуть. Кузьмич отвечать будет завтра.","Кузьмич отказался: «Не могу, он мне как родной». Покупатели ушли. Табличка висит. Мой снова пошёл смотреть.","Развязка: «Москвич» купил мой. Свой. Кузьмич два года разбирал НАШ — перепутал гаражи. Мой: «Говорил же — мой лучше»."]},{"id":"urok","t":"Валерка учится водить","ep":["Сан Саныч взялся учить Валерку водить. Урок первый — сесть. Валерка сел на место Сан Саныча. Урок продолжится завтра.","Урок второй: зеркала. Валерка увидел в зеркале меня на лавочке и пригнулся. Сан Саныч говорит — правильно, чутьё есть.","Урок третий: педали. Валерка спросил, зачем их три, если ног две. Сан Саныч отвечал так долго, что урок перенесли.","Мама Валерки узнала про уроки. Пришла к Сан Санычу с пирогом. С пирогом не поспоришь. Что она решила — завтра.","Мама разрешила. Условие: только по двору и только когда я на лавочке. Я согласилась. Я и так на лавочке.","Поехали! Метр. Валерка увидел Барсика и затормозил так, что Сан Саныч снял очки. Барсик спит. Завтра — два метра.","Два метра проехали. На третьем «Волга» кашлянула и встала. Сан Саныч говорит — погода. Погода хорошая.","Толик посмотрел «Волгу»: «Её саму никто никогда не учил». Сан Саныч обиделся за машину. Уроки — до примирения.","Сан Саныч помыл «Волгу» — помирились. Валерка учит правила. Выучил одно: «Баба Шура всё видит». Остальные — завтра.","Валерка объехал клумбу! Михалыч стоял с метлой наготове. Метла не понадобилась. Михалыч растерян — он уже замахнулся.","Экзамен — в субботу. Принимать буду я. Сан Саныч спросил, есть ли у меня права. Я сказала: у меня тетрадка. Он замолчал.","Валерка повторяет даже ночью. Мама слышала, как он во сне сказал «включаю поворотник». Гордится: раньше он во сне ел.","Экзамен! Валерка выехал, развернулся и встал ровно в разметку. Но разметку рисовал Михалыч. Решаем, засчитывать ли.","Засчитали! Валерке — справка «Водитель двора» и страница «хорошие» в тетрадке. Сан Саныч просится на пересдачу сам."]},{"id":"svadba","t":"Свадьба внучки Михалыча","ep":["Внучка Михалыча выходит замуж! Свадьбу хотят у нас во дворе. Михалыч третий раз подметает одно и то же место.","Жених приезжал знакомиться. На «Девятке». Встал на газон. Михалыч молчит. Это страшнее, чем когда он ругается.","Михалыч поговорил с женихом. О газоне. Два часа. Жених вышел другим человеком и переставил «Девятку» почти на руках.","Нужен кортеж. Жених хочет лимузин, Михалыч — «Чайку». У двора есть только «Буханка» Толика. Совет жильцов — завтра.","Совет решил: кортеж — из всех машин двора. Толик моет «Буханку», Сан Саныч — «Волгу». «Оку» — в конец. Без обсуждения.","Валерка украшает машины лентами. Ленты кончились на третьей машине. Дальше пошли мои бельевые верёвки. Вместе с бельём.","Репетиция кортежа! Выехала только первая машина. Остальные упёрлись друг в друга. Без тебя, похоже, не обойтись.","Михалыч написал речь: две страницы про невесту, семь — про газон. Внучка просит сократить. Он сокращает — про невесту.","Ночью перед свадьбой Михалыч подмёл двор. Потом соседний. Утром его нашли у метро. С метлой. «На всякий случай».","Свадьба! Невеста красивая, «Девятка» стоит ровно. Михалыч плакал. Говорит — пыль. Пыли нет: он же всё подмёл.","Кортеж тронулся. Первой — «Чайка»: Толик её всё-таки достал. Где — молчит. Записываю: «происхождение неизвестно».","Мой бросал рис. Попал в Барсика. Барсик ходит в рисе, как жених. Михалыч ищет, куда это подметать.","«Чайка» пропала! Стояла — и нет. Толик молчит. Пришёл мужчина в шляпе: «Не видели тут «Чайку»?» Мы видели.","Развязка: «Чайку» Толик взял в музее «на круг». Мужчина в шляпе — директор музея и дядя жениха. Тоже плакал. От пыли."]},{"id":"vybory","t":"Галя в старшие","ep":["Галя из 12-й объявила выборы старшей по двору. Против меня. Первые с восемьдесят третьего. Я спокойна: тетрадка у меня.","Галя повесила листовку: «Порядок без тетрадки!» Я — свою: «Тетрадка и есть порядок». Михалыч ворчит: клей на двери.","Галя обещает всем места у подъезда. Мест у подъезда четыре. Обещано девятнадцать. Я посчитала. В тетрадке.","Галя раздаёт пирожки. Покупные! Тётя Валя возмущена и теперь за меня. У тёти Вали пироги свои.","Дебаты. Галя: «Что вы сделали за сорок лет?» Я открыла тетрадку на первой странице. Дебаты продолжатся: страниц много.","Мой спросил, за кого голосовать. Я сказала — за кого хочешь. Он подумал и спросил ещё раз. Завтра спросит в третий.","Валерка — наблюдатель. Нарисовал себе бейджик: «Набюдатель». Не поправляем — он и так волнуется.","Галя говорит, что я записываю людей без спроса. Я записала: «Галя говорит». Протокол есть протокол.","Барсик лёг на Галину листовку и не встаёт. Говорят, это моя агитация. Я над котом не властна. Он над листовкой — да.","Голосование! Урна — коробка из-под запчастей Толика. Внутри нашлась деталь. Толик забрал её вместе с бюллетенем.","Подсчёт. Михалыч считает вслух. Галя — одиннадцать. Я — одиннадцать. Один бюллетень пустой. Чей — пока не знаю.","Пустой — моего. Говорит: «Не мог выбрать, вы обе хорошие». Сорок лет вместе — и «не мог выбрать». Дома будет разговор.","Мой голосует заново. Весь двор у подъезда. Он взял ручку. Посмотрел на меня. На Галю. Попросил чаю. Ждём.","Мой проголосовал за Галю. Через час она пришла: «Шура, а где тетрадка? Кто где стоит?» Я теперь советник. С тетрадкой."]},{"id":"ugon","t":"Пропал «Москвич»","ep":["Утром мой пошёл в гараж — а «Москвича» нет! Двадцать пять лет стоял. Сам уехать не мог: аккумулятора нет с 2003-го.","Составила ориентировку: «Москвич-412», цвет — когда-то синий, примета — не заводится. Повесила на доску. Жду звонков.","Опросила свидетелей. Барсик молчит. Голуби разлетелись — подозрительно. Михалыч видел ночью свет в гараже Толика.","Улика: у гаража след шин. Ширина — как у «Москвича». Ведёт к гаражу Толика. Толик говорит — совпадение. Проверим.","У Толика «Москвича» нет. Есть ключ на десять — тёплый. Толик говорит, он всегда тёплый. Записала: «ключ тёплый».","Мой второй день сидит у пустого гаража. Говорит: «Я ж его вывести собирался. Вот сегодня бы и вывел».","Участковый: «Когда последний раз видели машину на ходу?» Мой: «В девяносто восьмом». Участковый ушёл думать.","Валерка нашёл в соседнем дворе синий «Москвич». Сходили. Номер не наш. Зато кот на капоте — наш. Барсик тоже ищет.","Михалыч вне подозрений: у него метла и алиби — весь вечер мёл у всех на глазах. Вычёркиваю. С сожалением.","На доске записка: «Верну, когда починю». Почерк корявый, знакомый. Рядом — ключ на десять. Тёплый.","Ночью дежурю у гаража: я, тетрадка, термос. В три часа — шаги. Кто-то закатывал машину. В гараж. Свечу фонариком…","…Это мой. Тайком возил «Москвич» к Толику чинить — сюрприз к годовщине. Сегодня катил обратно: «не успели».","Значит, мой угнал собственную машину. Заявление забрала. Участковый: «Первый раз такое». Я: «Вы моего не знаете».","Годовщина. «Москвич» завёлся! Проехал два метра и встал у лавочки. Мой: «Нарочно — поближе к тебе». Романтик."]},{"id":"prava","t":"Шура сдаёт на права","ep":["Решила сдать на права. Сорок лет всех записываю — пора и самой. Мой сказал «наконец-то» и ушёл прятать «Москвич».","Купила «Оку». Подержанную. Продавец сказал: «Бабушке в самый раз». Я его записала. На отдельную страницу.","Первое занятие. Инструктор спросил, где у машины капот. Я спросила, почему он встал у пожарного гидранта. Ничья.","Теория: восемьсот вопросов. Кто где стоял с 1983-го — знаю. Знаки — хуже. Мой гоняет по билетам. С удовольствием.","Первый выезд. Двор смотрел из всех окон. Я проехала метр и записала, кто смотрел. Это внимание к обстановке.","Михалыч убрал с моего пути все урны. Клумбу бы тоже убрал, но петуньи я не отдам. Объезжаю. Медленно. С достоинством.","Галя сказала: «Шура за рулём — к беде». Я сказала: «Галя на балконе — к дождю». Сегодня дождь. Счёт открыт.","Параллельная парковка! Инструктор хвалит глазомер. Ещё бы: сорок лет смотрю, как паркуются другие. Знаю, как НЕ надо.","Барсик лёг на капот моей «Оки». Первый раз на маленькую машину. Значит, признал. Или мотор горячий — завтра узнаю.","Теория сдана! Девятнадцать из двадцати. Ошибка в вопросе «кто прав». Я ответила «я». В билете иначе. Билет неправ.","Площадка. Змейка, эстакада, «гараж». Задела флажок. Флажок там стоит по моему совету — с восемьдесят пятого.","Пересдача завтра. Мой принёс чай: «Шура, ты справишься». Сорок лет не говорил. Подозреваю, что-то натворил.","Натворил: записался ко мне на экзамен пассажиром. Для поддержки. Инструктор сядет сзади. Втроём в «Оке». Завтра.","Сдала! Записала в тетрадку: «Шура. «Ока». Стоит ровно». Галя в тот же день купила иномарку. Но это другая история."]},{"id":"inomarka","t":"Галя купила иномарку","ep":["Во двор въехала иномарка. Белая, огромная, блестит. Из неё вышла Галя. Двор замолчал. Даже голуби.","Галя говорит: машина «паркуется сама». Вышли всем двором смотреть. Машина припарковалась сама. Поперёк. Вся в хозяйку.","Иномарка заняла два места. Сан Саныч от обиды встал на третье. Теперь некуда встать Толику. На ком кончится — завтра.","Кончилось на мне: я хожу пешком. Место мне не нужно. Но я записала. Галя у меня теперь на двух страницах.","Иномарка пищит, когда к ней подходит Барсик. Барсик подходит часто. Двор спит плохо. Барсик — отлично.","Толик заглянул под капот иномарки. Вышел бледный: «Там нет ничего, что я понимаю. Даже места для ключа на десять».","Иномарка не завелась! Сервис — далеко, дорого, через неделю. Толик сказал: «Поглядим». Галя гордая. Пока.","Галя пришла к Толику с пирогом. Покупным. Толик пирог взял. Иномарку — нет. Его профиль — «Москвич».","Неделя без иномарки. Галя ходит пешком мимо лавочки. Здоровается! Первый раз за двадцать лет. Мой даже встал.","Валерка разобрался: ключ должен лежать рядом с машиной. Ключ — в летней сумке. Сумка — у сестры. Сестра — в Сочи.","Сестра шлёт ключ почтой. Неделю. Пока Галю возит Сан Саныч на «Волге». Она сидит сзади. Молча. Сан Саныч сияет.","Ключ пришёл! Иномарка завелась и первым делом встала поперёк. Галя счастлива: «Узнала хозяйку».","Галя решила иномарку продать: «двору не подходит». На самом деле Сан Саныч обещал возить её и дальше. Бесплатно.","Иномарку купил Кузьмич — на запчасти. Вчера Галя ехала с Сан Санычем уже спереди. Записала: «роман, предварительно»."]},{"id":"novosel","t":"Новосёл в 34-й","ep":["В 34-ю въехал новый жилец. Ночью. С одной сумкой и на «Шишиге». Ночью въезжают только два сорта людей. Выясню, какой.","Новосёл не здоровается — его просто не видно. «Шишига» стоит, окна тёмные. Михалыч видел его в пять утра с удочкой.","Посмотрела на ящик 34-й. Только посмотрела. Газета «Охота и рыбалка» и квитанция на фамилию… без очков не разобрать.","Барсик ходил в 34-ю. Вернулся довольный, пахнет рыбой. Барсик знает больше, чем говорит. Он вообще не говорит.","Валерка постучал в 34-ю «за солью». Бородатый мужчина дал соль. Килограмм. Спросил: «Хватит?» Валерка в смятении.","«Шишига» уехала в четыре утра. Вернулась в десять, грязная по крышу. Такая грязь у нас только у реки за гаражами.","Мой сказал: «Оставь человека в покое». Я оставила. На сутки. Записала: «оставлен в покое». Посмотрим, что сделает.","Новосёл поставил «Шишигу» точно в разметку. Ровно. Впервые в истории двора. Нормальные люди так не паркуются.","Тётя Валя отнесла ему пирожков. Вернулась с рыбой. Три карася — обмен. Пирожки он съел при ней. Значит, человек хороший.","Узнала фамилию! Не фамилия даже — все зовут Петрович. Тот, что с реки за гаражами. Но он же у реки и живёт…","Петрович объяснил: у реки дача, зимой холодно — переехал к нам. Барсик, оказывается, давно ходил к нему. За рыбой.","Петрович спрашивает: «Шура, вы всех знаете — где тут клюёт?» Я говорю: «У нас паркуются». Не понял. Объясню завтра.","Подвела к окну: «Вот этот двор надо каждый день разъезжать». Петрович посмотрел: «Как сеть распутывать». Понял, значит.","Петрович записан: «свой». Первый за двадцать лет, кто встал ровно. Мой ревнует: «Я тоже ровно стою». С 1998-го."]},{"id":"volga","t":"Чёрная «Волга»","ep":["Ночью во двор въехала чёрная «Волга». Без номеров. Постояла у подъезда и уехала. Я не испугалась. Я записала: 2:47.","Снова чёрная «Волга». Снова 2:47. Минута в минуту. Кто-то, значит, тоже ведёт тетрадку. Конкуренция.","Двор волнуется. Галя говорит — это за ней. Михалыч говорит — это за Галей. Мнения совпали. Двор успокоился.","Мой вспомнил: в семьдесят девятом у нас стояла такая «Волга». Чья — не помнит. Помнит, что мыл её за рубль.","Дежурю у окна. 2:47 — «Волга». Никто не вышел. Посветила фонариком. Фара мигнула в ответ. Вежливая.","Валерка снял «Волгу» на телефон. На снимке — темнота и Барсик на капоте. Даже ночью он на капоте. Даже на этом.","Участковый проверил чёрные «Волги» без номеров. «Таких в городе сорок». Я сказала: «А в 2:47 — одна». Он записал.","Толик подкрался к «Волге» с ключом на десять. Вернулся без ключа: «отдал». Кому — молчит. А ключ любимый.","Утром ключ лежал у меня на подоконнике. С запиской: «Спасибо, подошёл». Почерк учительский. Где-то я его видела.","Сверила с тетрадкой. Так писала Нина Петровна, старшая до меня. Уехала в восемьдесят третьем. Тогда я и стала.","Значит, это «Волга» Нины Петровны. Ей под девяносто. По ночам проверяет двор, как раньше. Я это чувство знаю.","Решила встретить. 2:46. Вышла с термосом. 2:47 — «Волга». Остановилась. Стекло медленно опускается…","За рулём — внук Нины Петровны. Бабушке ночью не спится, вот он и возит её по старым дворам. Она — сзади. С тетрадкой.","Нина Петровна мне: «Шура, у тебя «Ока» поперёк». «Ока» не моя! Но я записала. Теперь они заезжают к нам на чай."]},{"id":"pobeda","t":"Ржавая «Победа»","ep":["Толик купил на барахолке «Победу». Ржавую. Без колёс, мотора и дверей. Говорит: «Главное — характер есть».","«Победу» тащила на тросе «Буханка». На полпути «Буханка» устала. Толкали всем двором. Я руководила. С лавочки.","Толик снял с «Победы» ржавчину. Под ней — ещё ржавчина. Под той — номер кузова 1953 года. Толик говорит: паспорт есть.","Нужны колёса. Толик снял колёса с тачки Михалыча. Михалыч носит листья в руках. Молчит. Он копит.","Мой ходит смотреть на «Победу». Говорит: «На такой я тебя из загса вёз». Я: «На такой, но не на этой». Он задумался.","Мотор нашёлся у Кузьмича. Отдал за «спасибо». Спасибо Толик отдаёт частями — уже третий раз.","«Победа» чихнула! Первый раз за семьдесят лет. Двор вышел на звук. Барсик убежал. Тоже первый раз.","Красить решили «как была». Какой была — никто не помнит. Мой говорит — вишнёвая. Митяй — зелёная. Спор до завтра.","Спорили до утра. Покрасили наполовину вишнёвым, наполовину зелёным. Толик: так и было, в 1953-м краски не хватало.","Валерка нашёл в бардачке письмо: «Шура, приходи к гаражу в семь. С уважением…» Подпись размыта.","Шура — это я? Мало ли Шур. Мой подозрительно молчит. Уже второй день.","Мой признался: письмо его, шестьдесят девятого. Положил в бардачок отцовской «Победы». А отец машину продал. С письмом.","Толик сверил номер кузова. Это она! Пятьдесят лет по барахолкам — и вернулась во двор. Вместе с письмом.","«Победа» на ходу. Мой довёз меня до гаража. В семь. Опоздал на полвека с лишним. Говорит — пробки. Записала: «пришёл»."]},{"id":"domino","t":"Турнир по домино","ep":["Соседний двор вызвал наш на турнир по домино. Митяй принял вызов, никого не спросив. Сорок лет ждал.","Митяй тренируется сам с собой. Проигрывает себе через раз. Говорит: «Это я сильный».","Нужна команда из четырёх. Митяй, мой, Толик и… Валерка. Правил не знает. Митяй: «Тем лучше — не просчитают».","Соседи прислали разведчика. Ходил вокруг лавочки, разглядывал кости. Барсик посмотрел на него. Разведчик ушёл.","Мой по ночам стучит костями — разминается. Валерка дал мне наушники. Записал в них, как стучит мой. «Чтоб не скучали».","Михалыч сколотил для турнира новый стол. Ровный. Слишком: кости скользят. Митяй требует старый, кривой. «Он наш».","Тётя Валя печёт пирожки для болельщиков. Соседским — с капустой. Нашим — с мясом. Стратегия.","День турнира! Соседи приехали на «ЛАЗе», всем двором. Встали у нас так, что уехать им теперь не скоро. Это важно.","Первая партия — наша! Валерка поставил «пусто-пусто» не туда, и соседи сбились. Митяй: «Вот что значит не знать правил».","Вторая — соседям. Мой засмотрелся на пирожки. 1:1. Решающая — завтра. Соседи остались ночевать. Уехать-то не могут.","Ночью соседи пробовали выехать на «ЛАЗе». Упёрлись в «Волгу», потом в «Оку». Двенадцать попыток. Рекорд двора.","Решающая. Митяй и капитан соседей один на один. Стук костей. Тишина. Капитан говорит: «Рыба»…","…и Митяй говорит «рыба». В ту же секунду. Ничья? Михалыч принёс правила 1957 года. Ответ — на последней странице.","По правилам 1957 года при двойной «рыбе» побеждает двор, где чище. Михалыч мёл всю ночь. Мы чемпионы! «ЛАЗ» выводишь ты."]},{"id":"barsik","t":"Барсик пропал","ep":["Барсика нет со вчерашнего утра. Ни на одном капоте. Двор без него пустой — машины стоят как раздетые.","Обошла все капоты. Двадцать три. Тёплых — пять. Барсиков — ноль. Записала, у кого тёплый. Пригодится.","Объявления: «Пропал кот. Рыжий. Отзывается на тёплый капот». Михалыч видел рыжего у арки. Это был Валерка в шапке.","Сан Саныч сорок лет сгонял Барсика с «Волги». Теперь моет машину, и капот кажется ему голым. Скучает. Признался.","Михалыч нашёл на снегу следы лап. Ведут к арке. Дальше — асфальт. Следствие упёрлось в асфальт.","Валерка поставил на капот «Копейки» блюдечко молока. Пришли голуби. Отдел разведки работает, но только за еду.","Петрович видел рыжего кота у реки — сидел возле удочки. Но Петрович рыбачит в соседнем районе. Барсик путешествует?","Мой не спит. Говорит: «Он на моём «Москвиче» двадцать лет грелся. Ни разу не завёлся, а коту было тепло».","Звонок из соседнего двора: «У нас на капоте чужой рыжий кот, не уходит». Едем! Сан Саныч сам предложил «Волгу».","Приехали. На капоте — Барсик. Капот — той самой иномарки. Барсик посмотрел на нас как на незнакомых.","Разгадка: у иномарки подогрев. Круглые сутки. Барсик нашёл рай. Мы его уговариваем. Он слушает. Не встаёт.","Сан Саныч встал рядом и прогрел мотор «Волги». Барсик подумал. Остался на иномарке. Сан Саныч греет второй час.","Мой принёс одеяло, на котором Барсик спал на «Москвиче». Постелил на «Волгу». Барсик встал. Потянулся…","…и пересел на «Волгу». Едем домой пять километров в час. Дома Барсик сразу лёг на «Москвич». Сан Саныч обиделся."]}],"roman":["«Запорожец» влюбился в «Волгу». Она стоит у подъезда, он — у мусорки. Шесть метров и целая пропасть.","«Волга» его не замечает. Она вообще никого не замечает: у неё хромированный бампер и хозяин-начальник.","«Запорожец» попросил хозяина встать поближе к «Волге». Хозяин встал. Поближе к гаражу. Намёков не понимает.","Ночью «Запорожец» мигнул «Волге» фарой. Одной — вторая с весны не горит. Получилось, что подмигнул.","«Волга» сделала вид, что не заметила. Но утром завелась с первого раза. Сан Саныч удивлён. Я — нет.","«Копейка» всё видела и всем рассказала. Сигнал у «Копейки» громкий. К обеду знал весь двор.","Мусоровоз, мудрый, сказал «Запорожцу»: «Не торопись. Я к своему контейнеру тоже не сразу подъехал».","Хозяин помыл «Запорожца». Впервые с Олимпиады. Под грязью он оказался голубым. Двор ахнул.","«Волга» посмотрела на него. Впервые. Долго. И тут во двор въехала «Девятка». С тонировкой. И с музыкой.","«Девятка» встала рядом с «Волгой» и включила музыку. «Волга» вздрогнула всем кузовом. «Запорожец» тихо заглох.","«Девятка» каждый вечер играет «Волге» музыку. Громко. Двор не спит. «Волга», похоже, тоже.","Хозяин включил «Запорожцу» радио. Там шёл прогноз погоды. «Волге» понравилось: она ценит постоянство.","Галина «Ока» встала поперёк — ровно между «Девяткой» и «Волгой». Говорит, случайно. «Ока» случайно не встаёт.","Оказалось, «Ока» сама положила фару на «Девятку». Четырёхугольник. Мусоровоз пожал кузовом: «Видал и сложнее».","«Девятка» подарила «Волге» ёлочку-вонючку. «Волга» повесила её на зеркало. «Запорожец» не спал всю ночь.","Лучшая подруга «Запорожца», «Буханка», посоветовала: «Будь собой». «Запорожец» был собой. Не завёлся.","Михалыч подметал и подслушал: «Волга» спросила у «Победы», как та поняла, что это любовь.","«Победа» ответила: «Когда он отцепил меня с буксира, а я не уехала». «Волга» думала всю ночь.","Утром «Девятка» уехала на мойку. «Волга» осталась одна. И тут «Запорожец» тронулся с места…","…и проехал два метра! Встал рядом с «Волгой». Двор аплодировал. У «Оки» отвалилось зеркало.","«Волгу» увезли в гараж к Толику на ремонт. «Запорожец» стоит у пустого места. Ждёт. Не моргает.","Второй день без «Волги». «Девятка» по привычке играет музыку пустому месту. Или надеется.","У «Волги» барахлит мотор. «Запорожец» отдал бы свой. Но у него мотор сзади. Не подойдёт.","«Буханка» каждый день возит новости из гаража. Новости одни и те же: «Толик ищет ключ на десять».","Через неделю из гаража выехала красная «Волга». Незнакомая. Красивая. Двор замер.","«Девятка» тут же включила незнакомке музыку. «Запорожец» не смотрел. Он верный. Он ждёт свою — серую.","Незнакомка встала на место «Волги». «Ока» возмутилась. Мусоровоз хмыкнул: он что-то знает.","«Запорожец» всё-таки посмотрел на незнакомку. А она подмигнула. Одной фарой. Вторую Толик не доделал.","Это она! Сан Саныч попросил перекрасить «помоложе». «Девятка» неделю играла музыку той же самой.","«Волга» узнала: «Запорожец» узнал её первым. По подмигиванию. «Девятка» не узнала вовсе. Очко ушастому.","Приехала «Волга с оленем». Хром, олень на капоте, взгляд строгий. Наша «Волга» побледнела. Даже красная.","«Волга с оленем» встала напротив и смотрит. Час. Два. Олень на капоте, кажется, тоже смотрит.","«Ока» разузнала: «Волга с оленем» полвека ищет кого-то по всем дворам области.","Мусоровоз шепнул: «Двадцать первая — родня двадцать четвёртой. Почти мать». «Волга» в смятении.","«Волга» думала, что её собрали из запчастей. Так ей «Копейка» говорила. Всю жизнь.","«Копейка» призналась: соврала из зависти. Это она из запчастей. Наполовину — от «Москвича».","«Волги» встали бампер к бамперу. Олень кивнул. Михалыч сказал, что не плакал. Он подметал. Лицом.","«Волга с оленем» осталась ночевать. Рассказала всё: как ездила на юг, возила невест, как её хотели в музей.","«Запорожца» тоже представили. Олень посмотрел на него свысока. Сверху вниз у оленя выходит само.","Утром «Волга с оленем» уехала. Под дворником записка: «Ушастого держи. Таких не в музей сдают — таких любят».","Пока все смотрели на «Волг», «Девятка» стала проводить вечера у «Оки». Поперёк. Вдвоём.","«Волге» всё равно. Но фары она теперь включает на полчаса раньше. Чтобы лучше было видно.","«Ока» хвастается: «Девятка» сделала ей тюнинг. Наклеила полоску. Одну. Больше на «Оку» не помещается.","«Запорожец» ревнует «Волгу» к «Девятке», хотя та давно у «Оки». Мусоровоз говорит: ревность — как ржавчина.","Провела собрание машин. Повестка: кто с кем стоит. Решили: стоять по разметке. Никто не выполнил. Как у людей.","Ночью «Девятка» вернулась к «Волге» и включила их песню. «Волга» встала на ручник.","«Ока» всё видела. «Ока» обиделась. «Ока» встала поперёк всего двора. Утром никто не выехал. Выручал ты.","«Девятку» вызвали на разговор «Буханка» и Мусоровоз. «Буханка» молчала. Мусоровоз молчал громче.","«Девятка» раскаялась и выключила музыку на неделю. Двор впервые выспался. Михалыч предложил продлить.","«Ока» простила. Условие: музыка по выходным и только про неё. Песен про «Оку» не нашли. Ищут.","Пришла зима. Минус тридцать. Двор в снегу. Машины молчат. Заводиться никто не хочет.","Не завелась «Волга». Не завелась «Девятка». Даже Мусоровоз не приехал. Его, говорят, тоже не завели.","А «Запорожец» завёлся. С первого раза. У него воздушное охлаждение: ему мороз — как «Волге» комплимент.","«Запорожец» отвёз Сан Саныча на работу, Галю в магазин, а меня в поликлинику — за справкой для бассейна.","Весь двор говорит про «Запорожца». «Копейка» сигналит ему вслед. Из уважения. Или кнопка примёрзла.","«Запорожец» встал рядом с «Волгой» и полчаса грел её мотором. Как жених у подъезда.","«Волга» завелась! Толик говорит — аккумулятор подсел и отошёл. Я говорю — любовь. Толик: «Одно и то же».","«Девятка» попросила у «Запорожца» прикурить. Он помог. Молча. Только фарой мигнул. Одной.","«Волга» смотрит на «Запорожца» по-новому. Так смотрят на того, кто в мороз приехал первым.","Весной Сан Саныч сам поставил «Волгу» рядом с «Запорожцем». Сказал — «так удобнее». Я записала.","«Запорожец» решил познакомить «Волгу» с роднёй. Из деревни приехал «Горбатый» — его дед. Круглый и гордый.","«Горбатый» оглядел «Волгу»: «Большая. Где ж ты её ставить будешь?» Вопрос по делу. Записала.","«Победа» узнала «Горбатого». В шестидесятых они стояли у одного клуба. На танцах. Двор притих.","Оказалось, «Горбатый» был влюблён в «Победу». Не решился. Уехал в деревню возить картошку.","«Победа» призналась: ждала его тридцать лет у клуба. Потом клуб снесли, а её перевезли к нам.","«Запорожец» и «Волга» решили свести стариков. Устроили во дворе танцы. Музыку дала «Девятка».","«Горбатый» пригласил «Победу» на круг вокруг клумбы. Круг занял сорок минут. Никто не торопил. Даже Михалыч.","После танцев «Горбатый» остался. Насовсем. Рядом с «Победой». Картошку теперь возит «Буханка».","Мой смотрел на них с лавочки: «Как мы с тобой». Я: «Ты меня вокруг клумбы не возил». Он: «Так «Москвич» же».","Он пошёл заводить «Москвич». Не завёл. Но пошёл. Для моего это предложение руки и сердца.","Во двор заехал «Икарус». Гастролёр! Длинный, оранжевый, с гармошкой посередине. Двор заволновался.","«Икарус» рассказывает про Венгрию, Москву, Сочи. «Копейка» слушает с открытым капотом.","«Копейка» влюбилась. Впервые. Ей пятьдесят. Говорит, раньше было некогда — всех возила.","«Буханка» грустит. Она давно смотрела на «Копейку». Но «Буханка» трудяга, про Венгрию ей рассказать нечего.","«Икарус» обещал взять «Копейку» в рейс. Говорит, поместится у него в гармошке. Мусоровоз хмыкнул.","Мусоровоз знает: «Икарус» во всех дворах обещает «Копейкам» рейс. Мусоровоз объезжает все дворы.","«Копейка» ждала у арки всю ночь. «Икарус» уехал в пять утра. Без неё. Даже гармошку сложил тихо.","Утром «Копейку» нашла «Буханка». Отвезла домой на буксире. Ни слова не сказала. Просто встала рядом.","«Копейка» поняла: Венгрия — это хорошо, но домой на буксире везёт тот, кто стоит рядом.","«Копейка» и «Буханка» теперь ездят за хлебом вместе. Хлеба в «Буханке» так и нет. Зато есть «Копейка».","«Запорожец» решил сделать «Волге» предложение. Нужно кольцо. Толик выточил из поршневого. Красиво.","Кольцо повесили «Волге» на зеркало — вместо ёлочки «Девятки». «Девятка» вздохнула выхлопом.","«Волга» молчит третий день. «Ока» пустила слух, что та уезжает к начальству. «Запорожец» сторожит арку.","На четвёртый день «Волга» мигнула. Два раза. Толик проверил по справочнику: это «да».","Свадьба машин! Кортеж: «Горбатый» с «Победой», «Буханка» с «Копейкой», «Девятка» с «Окой».","Из города приехала «Волга с оленем». Олень в лентах. Мусоровоз приехал не во вторник — ради такого дня.","Поставить молодых рядом не вышло: двор заставлен гостями. Все стоят друг у друга на пути. Как всегда.","Гости разъезжаются. По одной. Кто первый — неясно. Кто мешает — все. Выручать, как обычно, тебе.","Двор опустел. Посередине — «Волга» и «Запорожец». Бампер к бамперу. Как мы с моим у гаража — полвека назад.","Конец сезона. Утром Сан Саныч сказал: «Опять «Запорожец» на моём месте». И не переставил. Записала: «женаты»."],"garage7":{"volga":["Ранее в сериале: Толик решил ехать с тобой по маршруту. Вместе с гаражом № 7.","Гараж погрузили на «Газон». Внутри Толик, табурет и ключ на десять. Поехали."],"ural0":["Ранее в сериале: гараж № 7 уехал со двора. Михалыч подмёл место, где он стоял сорок лет.","Урал. Гараж обледенел. Толик отогревает его чаем и разговорами."],"dv":["Ранее в сериале: на Урале Толик отогрел гараж чаем. Гараж оттаял, Толик — нет.","Дальний Восток. Гараж увидел океан и сам открыл ворота. Толик говорит — ветер."],"world1":["Ранее в сериале: гараж № 7 увидел океан. С тех пор скрипит воротами мечтательно.","Вокруг света! Гараж сдали в багаж. В графе «содержимое» Толик написал: «я»."],"world2":["Ранее в сериале: гараж прошёл таможню. Ключ на десять досматривали отдельно.","За границей Толик ищет ключ на десять. Там всё на тринадцать. Толик держится."],"zoloto":["Ранее в сериале: ключа на десять за границей нет. Толик вернулся домой — за своим.","Золотое кольцо. Гараж встал у монастыря. Туристы фотографируют: думают, старинный."],"piter":["Ранее в сериале: гараж № 7 приняли за памятник. Толик не спорил — постоял рядом.","Питер. Двор-колодец узкий. Толик снял ворота. Гараж прошёл. Ворота — нет."],"chernozem":["Ранее в сериале: в Питере гараж остался без ворот. Ворота догоняют на «Газели».","Черноземье. Земля такая, что Толик посадил у гаража болт. Ждёт урожая."],"moskva":["Ранее в сериале: Толик посадил болт в чернозём. Взошли две гайки.","Москва. Гараж поставили в спальном районе. Через час — три соседа и одна жалоба."],"arktika":["Ранее в сериале: в Москве на гараж написали жалобу. Он уехал, не дожидаясь ответа.","Арктика. Толик спросил, когда утро. Сказали — в феврале. Толик ставит чайник."],"karelia":["Ранее в сериале: за полярную ночь Толик перебрал табурет четыре раза.","Карелия. Гараж отражается в озере. Толик: «Гаражей теперь два, а чинить одному»."],"yug":["Ранее в сериале: в Карелии гараж увидел своё отражение. Расстроился: ржавый.","Юг. Толик в шляпе, гараж в тени. Отдыхающие спрашивают, почём койка."],"baikal":["Ранее в сериале: на юге Толик сдавал гараж под койку. Сам спал на табурете.","Байкал. Вода прозрачная: Толик увидел на дне ключ на десять. Не свой. Достал."],"zavod":["Ранее в сериале: на Байкале Толик достал со дна чужой ключ. Ключей теперь два.","Заводской Урал. Гараж увидел настоящий завод. Притих. Толик тоже. Уважение."],"dacha":["Ранее в сериале: гараж № 7 побывал на заводе и вышел с новым замком.","Дачи. Гараж приняли за сарай и поставили в него рассаду. Толик поливает."],"volga2":["Ранее в сериале: на даче в гараже выросли помидоры. Урожай — четыре штуки.","Волга-матушка. Гараж плывёт на пароме. Толик у ворот, как капитан. Ключ — как бинокль."],"altai":["Ранее в сериале: гараж переплыл Волгу. Капитана Толика укачало только раз.","Алтай. Гараж везут серпантином. Толик зажмурился и держит табурет."],"europe":["Ранее в сериале: в горах Толик не выпустил табурет. Табурет выжил.","Европа. Гараж поставили на площади. Думают, выставка. Толик берёт за вход."],"asia":["Ранее в сериале: в Европе на выставку «Гараж № 7» пришли двое. Один — голубь.","Азия. Гараж окружили мопеды. Сорок штук. Толик впервые чинит всё сразу."],"trassib":["Ранее в сериале: в Азии Толик починил сорок мопедов и выучил слово «ключ» на трёх языках.","Транссиб. Гараж на платформе. Толик пьёт чай из подстаканника и смотрит в окно. Окна нет."],"future":["Ранее в сериале: на Транссибе Толику так хотелось в окно, что он его прорубил.","Город будущего. Всё ездит само, чинить нечего. Толик открыл гараж: «Сломаются — придут»."]},"intercom":{"hello":["Это Шура. Не бойся, я не по делу. Хотя по делу: я всегда по делу.","Алло, это Шура. Звоню с домофона — с телефона дорого, а с домофона слышно на весь подъезд.","Это Шура. Ты спишь? Ничего, я подожду. Я с шести утра жду.","Доброе утро, это Шура. Открывать не надо — я уже вошла, у меня ключ от всего.","Это Шура. Звоню первой, пока Галя не позвонила. Она тоже собиралась, я видела.","Это Шура. Не пугайся: домофон у нас хрипит. Это не я сердитая, это провод старый.","Алло! Шура говорит. Мой спрашивает, с кем я разговариваю. С домофоном, говорю. Он не поверил.","Это Шура, с лавочки. Лавочка сегодня сухая — значит, день хороший. Вчера была мокрая, а день всё равно был хороший.","Это Шура. Звоню доложить. Мне никто не велел, но кто-то же должен.","Доброе утро. Это Шура, старшая по двору. Остальные пока младшие, спят.","Это Шура. Я коротко. У меня тетрадка на сорок восемь листов — коротко не получится.","Алло, Шура на проводе. На проводе домофона — я его сорок лет держу, он без меня не работает.","Это Шура. Ты не думай, я не каждому звоню. Только тем, кто в тетрадке. В тетрадке все.","Это Шура. Михалыч уже подмёл, Барсик уже лёг, а я уже звоню. Порядок.","Доброе утро, {name}. Это Шура. Я твоё имя в тетрадку ручкой записала, не карандашом. Это серьёзно.","Это Шура. Звоню из первой квартиры. Первая — потому что первой всё узнаю.","Алло. Это Шура. Если это не {name}, а кто-то другой, — всё равно слушайте, вам тоже полезно.","Это Шура. Мой говорит — звонить в такую рань неприлично. Сам он проснулся в пять. От моей тишины.","Это Шура. Начну с хорошего: двор на месте. Его никто не увёз, я проверяла.","Это Шура. Ты вчера рано ушёл. Ничего, я за тебя досидела."],"night":["За ночь ничего не случилось. Я специально не спала, чтобы это подтвердить.","Ночью Барсик сидел на «Волге» до трёх. Хозяин не знает. Барсик знает, что я знаю.","Ночью приехал кто-то на «Шестёрке» и встал поперёк. Номер я записала. Цвет — тоже. Характер — по стоянке видно.","Ночью было тихо. Подозрительно тихо. Утром выяснилось — Толик заснул в гараже, вот и не стучал.","Ночью Михалыч выходил с фонариком искать метлу. Метла стояла у него в прихожей. Записала обоих.","За ночь заставили весь двор. Как — не знаю, я на минуточку закрыла глаза. С двух до шести.","Ночью пришёл снег, ушёл снег. Двор сделал вид, что так и было. Я — нет.","Ночью кто-то посигналил. Один раз. Весь дом проснулся и до утра обсуждал, кто. Я знаю кто.","Ночью голуби держали собрание на козырьке. Повестку я не разобрала, но решение, по-моему, против Михалыча.","Ночью у Гали горел свет до часу. Не моё дело. Но записала.","Ночью мой встал попить воды и рассказал мне, что во дворе всё спокойно. Он смотрел в шкаф.","Ночью приезжала Скорая — к соседям через двор. Наша Петровна вышла на балкон узнать, не за ней ли. Обиделась.","Ночью Валерка вылез в окно посмотреть на звёзды. Звёзды на месте. Мама Валерки — тоже, теперь.","За ночь «Москвич» деда не завёлся. Дед его и не заводил. Но он не завёлся — это я видела.","Ночью у подъезда кто-то оставил самокат. Самокат я записала как жильца — пока хозяин не найдётся.","Ночью был ветер. Унёс объявление про собрание. Собрание теперь, видимо, у соседнего дома.","Ночью приехал Мусоровоз и ждал утра. Самый пунктуальный у нас: приезжает заранее и ждёт, пока все проснутся. От него.","Ночью дежурила я, а снилось мне, что дежурит Галя. Проснулась в холодном поту.","Ночью двор спал, машины спали, я записывала, кто как спит. «Волга» — ровно. «Ока» — поперёк.","За ночь ничего не произошло, кроме луны. Луну я тоже записала: стояла низко, выезд не загораживала."],"rumor":["Говорят, ты вчера {n} машин вывел. Галя говорит — {m}. Галя вчера сама не выехала, ей виднее.","Во дворе рассказывают: вчера {n} машин. На рынке уже говорят — {m}. К обеду дойдёт до сотни, я прослежу.","Мой спросил, сколько ты вчера вывел. Я сказала — {n}. Он пересказал Митяю, вышло {m}. Мужчины.","Вчера ты вывел {n}. Я сказала соседкам — {m}. Не обманула: я считаю с запасом, на будущее.","Валерка в школе рассказал, что знает человека, который вывел {m} машин за день. Это ты, только вчера было {n}.","По двору идёт слух: {n} машин и ни одной жалобы. В соседнем дворе говорят — {m}, и жалоба одна, от Гали.","Вчера {n}. Михалыч говорит — {m}: он считает по следам на асфальте, а следов всегда больше.","Я вчера в тетрадку написала {n}. Утром смотрю — исправлено на {m}. Почерк не мой. Почерк Валерки.","Говорят, вчера у тебя было {n} машин. В очереди в поликлинике — уже {m}. Там всё растёт, кроме очереди.","Толик клянётся, что ты вчера вывел {m}. Я его поправила: {n}. Он сказал: «Ну, с моей помощью было бы {m}».","Вчера {n} машин. Митяй говорит, в семьдесят восьмом выводили {m}. Машина тогда была одна — её {m} раз и выводили.","Слух такой: ты вывел {n}. В парикмахерской спорят — {m}. Там всегда спорят в твою пользу, если сидишь под феном.","Вчера {n}. В соседнем подъезде рассказывают — {m}, и что ты на «Икарусе». Не разубеждай, им приятно.","Говорят, ты вчера вывел {n}. Барсик ничего не говорит, но смотрит так, будто {m}.","Почтальонка спросила, правда ли {m}. Я сказала, вчера было {n}, а {m} — это сегодня, если поторопишься.","Вчера ты вывел {n} машин. Мой рассказывает, что {m} — и что это он тебя научил. Он и машину-то не выводил.","Вчера {n}. Собрание жильцов уже округлило до {m}. Собрание всё округляет — особенно сроки ремонта.","Вчера {n}. На лавочке решили, что {m}. Я голосовала против: зачем врать, когда и {n} хорошо. Но меня перевесили.","Тётя Валя в булочной говорит: «Это тот, который {m}». Я не стала поправлять — {n} тоже звучит, но хуже для пирожков.","Слух о тебе растёт. Вчера было {n}, к вечеру будет {m}. Я этот слух не распускала. Я его только поливала."],"today":["gift|Гостинец я тебе приготовила. Лежит в фартуке, греется. Не приходи слишком поздно — фартук привыкает.","gift|Сегодня гостинец есть. Какой — не скажу. Скажу только, что Галя спрашивала, а ей я не дала.","gift|Гостинец ждёт. Я его два раза перекладывала с места на место, чтобы не скучал.","gift|Забери гостинец. Мой уже два раза спрашивал, чей он. Третий раз — съест.","gift|Гостинец сегодня особенный. Как вчера. Я их все считаю особенными, у меня характер такой.","daily|Сегодня задание дня — один двор на всех. Я всем сказала, что ты его уже прошёл. Иди проходи.","daily|Задание дня вывесили. Я его прочитала первой, до Михалыча. Ничего страшного, но шлагбаум бы я туда не ставила.","daily|Новый двор дня. Сложный. Я туда утром выходила посмотреть — постояла и ушла. Тебе проще: ты не на ногах.","daily|Двор дня один на весь район. Пройдёшь первым — я узнаю. Вторым — тоже узнаю, но никому не скажу.","daily|Задание дня ждёт. Валерка с утра пробовал, получилось у него «почти». Почти — это у нас в тетрадке не считается.","week|На этой неделе собираем двор недели. Каждый вывел — двору плюс. Галин двор отстаёт. Я не радуюсь. Внешне.","week|Двор недели в этот раз — на учёте у меня лично. Так что без глупостей, всё будет записано красиво.","week|На неделе субботник. Тебе мести не надо — тебе выводить. Мести будет Михалыч. Он ещё не знает.","week|Итоги недели в воскресенье. Я уже сейчас знаю, кто молодец. Но порядок есть порядок: объявлю в воскресенье.","week|Двор недели продвигается. Мой тоже помогает — сидит на лавочке и не мешает. Это у него вклад.","mail|Письмо твоё получила. Прочитала. Ответ положила в ящик. Ящик старый — дёргай посильнее.","mail|Ответила на твоё письмо. Писала от руки, потом переписала начисто. Черновик лежит у меня — это для истории.","mail|Твоё письмо я прочитала два раза: один раз себе, второй — Барсику. Барсик одобрил. Ответ в ящике.","mail|Есть тебе ответ. Я его утром дописала, пока все спали. Если почерк кривой — это я торопилась, а не злилась.","mail|Письмо пришло — ответ ушёл. Мой спросил, кому я пишу. Сказала — тебе. Он теперь переживает, что не ему."],"later":["Потом так потом. Я никуда не денусь. Я тут с восемьдесят третьего.","Хорошо, перезвоню попозже. Домофон я не выключаю, он и так сам по себе.","Ладно, беги. Новости не скиснут — я их в холодильник положила.","Понимаю, дела. У меня тоже дела — вот, тебе звоню.","Потом — значит, потом. Запишу в тетрадку: «Потом». Там такая графа есть, мой её завёл.","Ничего, я не обиделась. Обижается у нас «Москвич» деда, а я — нет.","Хорошо. Скажу Гале, что ты занят. Важно занят.","Иди, иди. Я дочитаю двору, двор потом тебе перескажет.","Договорились. Я пока чайник поставлю. Второй раз за утро, но кто считает. Я считаю.","Потом так потом. Только «потом» у нас во дворе — это до вечера, а не до девяносто восьмого, как у моего."],"quiet":["Шура: «Звонить не буду, оставлю записку». Записка на двери подъезда.","Шура звонить не стала — передала через Барсика. Барсик ничего не сказал, но смотрит со значением.","Тихая новость дня от бабы Шуры — в тетрадке, страница сегодняшняя.","Шура молчит. Сказала, что ты знаешь, где её найти: лавочка, первая квартира, домофон.","Записка от Шуры: «Не звоню — не мешаю. Но всё записываю».","Шура сегодня без звонка. Говорит, сэкономила домофон. Домофон, кажется, расстроился.","От Шуры коротко: двор на месте, гостинец на месте, она на месте.","Шура передала через Михалыча, что звонить не будет. Михалыч передал через метлу.","Шура сегодня не звонит. Она стоит у окна, чтобы ты знал, что она не звонит.","Новость дня — строкой, без звонка. Шура бережёт твоё время. И свой голос — к собранию."]},"doc":{"harakter":{"head":"ХАРАКТЕРИСТИКА с места жительства","lines":["Дана водителю {name}: проживает у нас во дворе с {date}. Ведёт себя тихо, выезжает громко.","За время проживания вывел {n} машин. Ни одна не вернулась с жалобой.","В порочащих связях не замечен. Замечен в связях с «Волгой» — регулярно, но по делу.","Морально устойчив. Устойчивее «Оки» на повороте.","Клумбу не трогал. Клумба подтверждает.","Характер выдержанный. Выдержал двор {best}, а его не все выдерживают.","На собраниях жильцов не спорит. Потому что не ходит. Это тоже уважение.","Аварий за отчётный период: {n}. Все — в рамках знакомства между машинами.","С соседями вежлив. С Галей — вежлив особенно, на всякий случай.","В быту скромен. Подсказки берёт, только когда совсем надо. Или когда я подсказываю сама.","Пользуется авторитетом у Валерки. Валерка теперь говорит «как {name}» вместо «как папа».","Хорошо ориентируется в пространстве двора. Лучше, чем Михалыч в собственной метле.","Дисциплинирован: заходит {days} дней. Мой столько раз за год на зарядку не выходит.","К имуществу двора бережен. Лавочку не занимал, мою — особенно.","Замечаний от участкового не имеет. Участковый тоже не имеет — он с нами давно смирился.","Барсика не беспокоил. Барсик беспокоил его, но это у Барсика работа такая.","Регион {reg} освоил. Местные бабушки отзываются хорошо, но сдержанно.","Ночью выезжал тихо, фарами в окна не светил. В моё — светил, но я всё равно не спала.","Знания правил двора: отличные. Правил у нас одно — меня слушать.","Склонен к выездам без единой царапины. Это лечится, но мы не будем.","Отношение к труду: положительное. Толик говорит — подозрительно положительное.","Взысканий не имеет. Поощрения: пирожок от тёти Вали — 2 шт., с капустой.","Рекомендуется к дальнейшему проживанию. Альтернатив нет: двор его не отпускает.","Выдана для предъявления по месту требования. Требовать у нас некому — предъявляй родне.","Составлено по наблюдениям с лавочки. Наблюдения ведутся с 1983 года, непрерывно."]},"spravka":{"head":"СПРАВКА","lines":["Дана водителю {name} в том, что он действительно вывел {car} из двора {lv}. Свидетель — я. Я всегда свидетель.","Дана в том, что {name} прошёл двор {lv} без единой царапины. Царапины проверены лично, с очками и без.","Дана в том, что {name} является водителем первого класса нашего двора. Класс у нас один, но он первый.","Дана в том, что {name} освободил весь регион {reg}. Регион теперь пустой и не знает, что с собой делать.","Дана в том, что {name} заходит во двор {days} дней. Справка действительна, пока заходит.","Дана в том, что {name} вывел {n} машин. Машины претензий не имеют, хозяева — тоже, кроме одного. Его мы не спрашивали.","Дана в том, что {name} пропустил Скорую. Петровна передаёт спасибо. Ей всегда лучше, когда её пропускают.","Дана в том, что {name} не наезжал на клумбу. Клумба тоже выдала справку, но она неразборчивая.","Дана в том, что {name} вывел «Икарус». Кто выдал разрешение «Икарусу» въехать — выясняем с девяносто первого.","Дана в том, что {name} обыграл двор {best}. Двор об этом уведомлён и тяжело переживает.","Дана в том, что {name} знает домофон бабы Шуры. Код не скажу — его и так знает весь подъезд.","Дана в том, что {name} пропустил бабушку Клаву на переходе. Клава просила отметить, что в новой шляпке.","Дана в том, что {name} не сигналил ночью. Сигналил днём — это разрешено, это для бодрости.","Дана в том, что {name} вывел «Оку» Гали. Галя справку оспаривает. Справка остаётся в силе.","Дана в том, что {name} прошёл задание дня. Первым — по моим данным. По Галиным — вторым. Мои данные точнее.","Дана в том, что {name} — свой. Свой у нас — это когда я за тебя переживаю больше, чем за «Москвич» моего.","Дана в том, что {name} помогал Толику в гараже. Толик подтверждает, что помогал больше, чем Толик.","Дана в том, что {name} может водить автобус во дворе. Автобусу об этом не говорите — он стесняется.","Дана в том, что {name} освободил двор за {n} ходов. Михалыч столько раз за утро метлой не взмахивает.","Справка выдана для предъявления родне. Родне показывать с выражением, лучше вслух."]},"propusk":{"head":"ПРОПУСК ВО ДВОР","lines":["Пропуск во двор {lv}. Предъявителю — проехать. Если предъявитель застрянет — позвонить {name}.","Податель сего — гость водителя {name}. Пропустить, напоить чаем, показать, где «Волга».","Действителен один раз. Второй раз — по знакомству, а знакомство — это я.","Пропуск выдан на двор {lv}. {name} прошёл его за {n} ходов. Подателю предлагается хотя бы за {m}.","Шлагбаум открыть. Пульт у Михалыча. Михалыч в отпуске. Открыть мысленно.","Предъявителя не задерживать. Задерживать только «Оку» Гали, она и так задерживается.","Пропуск ко двору {lv}. Машины стоят как стояли. Я лично следила, чтобы никто не уехал до тебя.","Предъявитель — родня {name}. Родню у нас пропускают без очереди, но с расспросами.","Пропуск подписан старшей по двору. Других подписей не требуется. Других подписей у нас и не бывает.","Въезд с девяти до девяти. Выезд — когда получится. Обычно получается к вечеру.","Пропуск на одно лицо и одну попытку. Если попыток больше — я отвернусь.","Предъявитель вызван на двор {lv} водителем {name}. Ставки: честь подъезда.","Пропускать без досмотра. Досмотр проведу сама, с лавочки.","Пропуск дан для дружеского соревнования. Ругаться потом — только на лавочке, в отведённые часы.","При утере пропуска обращаться в первую квартиру. Там всё помнят и без пропуска."]},"sign":["Старшая по двору А. Ш.","Печать: тетрадка, стр. 47","Подпись: баба Шура. Заверено Барсиком (лапой)","Свидетель: я. Я всегда свидетель","Печать двора (круглая, от банки варенья)","Сверено с тетрадкой учёта с 1983 г.","М. П. (место печати занял Барсик)","Подписано при свидетелях. Свидетель — мой, он не спал","Копия верна. Оригинал у меня в фартуке","Выдано в первой квартире. Часы приёма: всегда"]},"letter":{"topics":{"hard":["Двор не пускает? Значит, ты ему нравишься. Начни с той машины, что стоит у самого выезда, — она тоже хочет домой.","Трудный двор — как мой: с виду не сдвинешь. Ищи, кто первым может уехать, и не торопись. Я подожду.","Знаю этот двор. Я сама его три раза мысленно расставляла. Нажми подсказку — я в ней сижу.","Не пройти — не беда. Отложи до завтра: утром машины сговорчивее, проверено сорока годами.","Сначала ищи маленькие машины. Большие гордые — уезжают, только когда для них всё уже готово. Как начальство.","Застрял — значит, двор хороший, держит. Начни с конца: какая машина уедет последней? Её и не трогай пока."],"bug":["Спасибо, что написал. Передала мастеру — он у нас и чинит, и красит. Как поправит — я первая скажу.","Ошибку записала в тетрадку, на отдельную страницу, красной ручкой. Красная у меня только для важного.","Неполадку передала куда надо. Пока чинят — не сердись на двор, он не нарочно.","Записала всё, как ты написал, слово в слово. Мастер прочитает и поправит. Он хороший, только медленный.","Спасибо, что сказал. Без тебя бы не узнали: я в телефоне не разбираюсь, я разбираюсь в людях.","Ошибка — это плохо, а письмо — хорошо. Чинить будем. Если повторится — напиши ещё, я не устану."],"thanks":["Спасибо и тебе. Я твоё письмо на холодильник повесила. Мой спросил, от кого. Сказала — от поклонника.","Читала и улыбалась. Галя видела — теперь думает, что мне пенсию прибавили.","Спасибо! Записала тебя на страницу «хорошие». Там пока ты, мой — до свадьбы, и тётя Валя за пирожки.","Приятно. Сорок лет во дворе — и в первый раз благодарят письменно. Устно — обычно жалуются.","Спасибо. Передала всему двору. Михалыч сказал «служу двору» и пошёл мести. Он так радуется.","Получила, прочитала, заплакала немножко. Мой подумал, что лук режу. Пусть думает."],"idea":["Мысль хорошая, записала. Передам мастеру. Он идеи любит — когда они не его, работать веселее.","Идею прочитала вслух на лавочке. Митяй сказал, в семьдесят восьмом было так же. Значит, надо делать.","Записала в тетрадку, в графу «предложения жильцов». Графа была пустая с девяносто шестого. Спасибо, оживил.","Хорошая затея. Вынесу на собрание. Собрание у нас всё одобряет, если к нему пирожки.","Идея понравилась даже Гале. Я сама удивилась. Передала мастеру — пусть думает, пока Галя не передумала.","Записала. Мой сказал, что он первым это придумал. Не верь — он только про обед первым придумывает."],"ad":["Понимаю, реклама мешает. Без неё двор не проживёт — это как взносы в ЖЭК. Но часто её не будет, я слежу.","Про рекламу записала. Её не больше раза в несколько дворов, а первые дворы — без неё. Передам, что мешает.","Реклама — как Мусоровоз: никто не любит, а без него никак. Я договорилась, чтобы приезжал пореже.","Спасибо, что сказал прямо. Рекламу посмотрим, где можно убрать. Ролики за подсказку — только когда сам захочешь.","Я тоже её не люблю — громкая. Передала мастеру твои слова. Он обещал не ставить её посреди двора.","Записала. Ролики за награду смотреть не обязательно — двор и без них проходится. Медленнее, но честно."],"money":["Монеты копятся за каждый двор, а гостинцы у меня — каждый день. Заходи — и кошелёк потолстеет.","Монет мало? Это у всех так, кроме Толика: он их в банку прячет и забывает. Заходи за гостинцем.","Монеты даются за дворы и звёзды, а ещё сундуки за звёзды. Покраска подождёт — машина не обидится.","Монеты дело наживное. Я сорок лет наживаю — нажила лавочку. Но лавочка хорошая.","Не трать всё на подсказки: я и бесплатно подскажу, если подождать. Мой вот ждёт с девяносто восьмого.","Записала твою просьбу. Монет просто так не дам — но гостинец завтра будет, это обещаю."],"car":["Про машину прочитала. Мой сразу вспомнил свой «Москвич». Час рассказывал. Спасибо, конечно.","Хорошая машина. Я её во дворе видела — стоит красиво, выезжает ещё красивее.","Толику показала твоё письмо. Он сказал, что такую машину собирал бы с удовольствием. Разбирал бы — тем более.","Машину твою записала в тетрадку, с цветом. Цвет у меня в тетрадке — как у людей фамилия.","Ты про машину — а я про хозяина. Хозяин, видно, хороший: про плохую машину не пишут.","Машины у нас во дворе с характером. Твоя — тоже. Я её узнаю по тому, как она на меня смотрит фарами."],"love":["Ой, спасибо. Двор тоже тебя любит — он просто стесняется, поэтому так заставлен.","Твоё письмо я прочитала Барсику. Барсик промолчал, но хвост поднял. Это у него «взаимно».","Любишь игру — значит, свой. Своих я в тетрадке подчёркиваю двумя чертами.","Признание приняла. Записала в графу «приятное». Графа до этого была только про пирожки.","Спасибо. Мой мне так в восемьдесят третьем писал. Потом перестал — сказал, что я и так всё знаю.","Раз нравится — заходи почаще. Я двор каждый вечер заставляю, чтобы утром тебе было что выводить."],"lonely":["Пиши мне, когда захочется. Я всегда на лавочке, мне не трудно ответить — мне приятно.","Ты не один. У тебя есть двор, а у двора есть я. Заходи каждый день — я буду ждать.","Спасибо, что поделился. Позвони кому-нибудь из своих сегодня — им тоже приятно будет. А потом приходи во двор.","Мне тоже бывает тихо. Тогда я выхожу на лавочку и здороваюсь со всеми. Даже с машинами. Становится легче.","Я тебя записала в тетрадку, на первую страницу. Там те, про кого я думаю каждое утро.","Поговорить всегда можно. Пиши — я прочитаю и отвечу. И гостинец тебе будет каждый день, я не забываю."],"health":["Береги себя. Двор подождёт сколько нужно — машины никуда не уедут без тебя.","Выздоравливай. Играй понемногу, отдыхай побольше. Я за двором пригляжу.","Спасибо, что написал. Слушай врача, а двор — потом. Я гостинцы буду откладывать, ничего не пропадёт.","Желаю здоровья тебе и твоим. Если глазам тяжело — в настройках есть спокойный режим, там поменьше мигает.","Не торопись. У нас во дворе ничего не сгорает — ни гостинцы, ни дворы. Ты главное сам поправляйся.","Держись. Весь двор за тебя. Даже Барсик: он сегодня лёг у двери, как будто ждёт."],"age":["Семьдесят — самый возраст для двора: видно всё и спешить некуда. Я тебя понимаю как никто.","Мне тоже не двадцать. Зато мы с тобой знаем, как раньше ставили машины. Плохо ставили — но красиво.","Возраст у нас во дворе только для уважения. Митяю восемьдесят — он всех в домино обыгрывает. Сам с собой.","Рада, что играешь. Если буквы мелкие — кнопка с лупой во дворе поможет. Я ею тоже пользуюсь.","Прекрасно, что ты с нами. Молодые торопятся и бьются, а мы — с толком. Посмотри на свои звёзды.","Годы — это опыт. Вот у меня опыт: я помню, кто где стоял в восемьдесят третьем. Тебе такой тоже пригодится."],"grandkids":["Внукам привет! Пусть приходят во двор — Валерке будет с кем спорить, где право.","Играете с внуками? Правильно. Только руль не отдавай сразу — пусть сначала посидят на лавочке, поучатся.","Внуки — это хорошо. Мой своему внуку обещает «Москвич». С девяносто восьмого обещает.","Покажи внукам двор с «Икарусом» — пусть знают, что бабушка-дедушка у них ас.","Передай внукам: баба Шура всё видит, так что выводить аккуратно. И бабушку-дедушку слушать.","Внуки помогли написать письмо? Значит, хорошие. Записала их в тетрадку, в графу «смена»."],"complaint":["Жалобу приняла. Записала всё как есть, без сокращений. Будем разбираться — я такие вещи не бросаю.","Обидно, понимаю. Передала мастеру твои слова. Спасибо, что написал, а не молча ушёл.","Ты прав, что сказал. Порядок во дворе держится на тех, кто говорит. Будем поправлять.","Записала. Если что-то конкретное не так — напиши, в каком дворе и что было. Так быстрее найдём.","Спасибо за честность. Я сорок лет на собраниях — жалоба для меня это забота, а не ругань.","Жалоба принята, номер в тетрадке. Отвечу, когда поправят. Я своё слово держу."],"question_how":["Нажми на машину — она поедет, куда смотрит стрелка. Впереди кто-то стоит — будет бум. Сперва освободи дорогу.","Смотри на стрелки на машинах — это куда они хотят. Ищи ту, перед которой дорога пустая, её и выпускай.","Если застрял — кнопка «Подсказка». Она подсветит машину, которой пора ехать. Это я подсвечиваю.","Звёзды дают за то, сколько ходов и аварий. Чем аккуратнее — тем больше звёзд. Как у меня в тетрадке.","Сердечки — это сколько раз можно стукнуться. Кончились — двор начинается заново. Не страшно, машины не помнят.","Эвакуатор увозит одну машину, которая мешает. Используй, когда совсем никак, — Толик потом её починит."],"slow":["Тормозит — передала мастеру. Попробуй в настройках спокойный режим: там меньше эффектов, телефону легче.","Записала. Иногда помогает закрыть другие программы — им тоже надо отдыхать. Мастер посмотрит.","Спасибо, что сказал. Телефоны у всех разные, у меня вот кнопочный. Мастер будет ускорять.","Понимаю, неприятно. Передала. Пока — попробуй перезапустить игру, двор тебя дождётся.","Записала, на каком телефоне. Мастер говорит, это важно. Я говорю, важно, что ты не бросил.","Будем чинить. А пока не торопись: у нас двор, а не гонки. Хотя Валерка спорит."],"music":["Музыку включают в настройках, кнопка «Музыка». Валерка перевёл название: «Беззаботная жизнь». Как у Барсика.","Музыка нравится? Мне тоже. Я под неё бельё вешаю. Мой — засыпает. Каждому своё.","Музыка выключается и включается в настройках. По умолчанию она тихая, чтобы соседей не будить.","Спасибо за отзыв про музыку, передам. Мой просит гармонь. Я сказала: вынесем на собрание. Собрание у нас — это я.","Музыку можно включить отдельно от звука. Я так и делаю: машины молчат, а мне весело.","Записала пожелание. Новую музыку не обещаю, но мастер подумает. Он под неё работает."],"sound":["Звук — в настройках, первая кнопка. Если на телефоне тишина стоит — проверь и там.","Без звука играть можно, машины не обидятся. А сигналы я и так слышу — у меня окно открыто.","Записала про звук. Если на айфоне тихо — проверь громкость сбоку. Мастер говорит, она коварная.","Слишком громко? В настройках можно выключить. Или как я — сделать вид, что не слышу.","Спасибо. Передала мастеру. Звук у нас простой — гудки и стуки. Как в настоящем дворе.","Нет звука — попробуй коснуться экрана, иногда телефон ждёт разрешения. Как Михалыч — пока не попросишь, не подметёт."],"night":["Играешь ночью? Я тоже не сплю. В ночном дворе фары горят — красиво, и никто не мешает.","Ночью двор тихий, а ты в нём хозяин. Только не забывай спать. Я вот забываю, потом весь день как «Ока» — поперёк.","Ночная смена — уважаю. Записала тебя в «ночные сторожа». Мой тоже ночной сторож: сторожит подушку.","Ночью звук потише — соседи. А так играй: машины ночью сговорчивее, проверено.","Ночью ты — я днём. Вместе мы двор круглые сутки держим. Хорошая у нас смена.","Знаю, ночью выезжаешь. Я видела: свет из окна. В своём я тоже свет видела — это я тебя ждала."],"newcomer":["Добро пожаловать во двор! Я баба Шура, старшая. Тут каждая машина на учёте. Теперь и ты.","Новенький — это хорошо. Я новеньких люблю: они ещё не знают, где Галя ставит «Оку».","Рада, что пришёл. Не торопись, выводи по одной. А гостинец завтра будет — запомни дорогу.","Первые дворы простые, дальше интереснее. Я тебя по ступенькам проведу, как по лестнице в подъезде.","Записала тебя в тетрадку на последнюю страницу. Не обижайся — она самая свежая.","Ты у нас новенький, но я уже вижу — свой будешь. По письму видно: вежливый."],"veteran":["Ты у нас давно. Я твою страницу в тетрадке уже дважды подклеивала — так много записей.","Старожилу — поклон. Без тебя двор не тот: даже Михалыч бы растерялся, кому кивать по утрам.","Сколько ты дворов прошёл — я сбилась. А я не сбиваюсь, у меня тетрадка с восемьдесят третьего.","Ветеранам двора у нас почёт: место на лавочке рядом со мной. Мой подвинется. Ворча.","Ты, считай, правая рука двора. Если что — я на тебя рассчитываю. На собрании скажу, что ты за.","Давно с нами — спасибо. Ты двору как родной. Он тебя уже не отпускает — заметил?"],"galya":["Про Галю? Галя из двенадцатой. Хорошая женщина. Только «Оку» ставит поперёк. Сорок лет. Стиль, говорит.","Галя мне не соперница. Соперница — это когда наравне. Шучу. Галя хорошая, мы с ней чай пьём. Спорим — потом.","Галя спрашивала, кто мне пишет. Я сказала — {name}. Теперь она тоже хочет, чтобы ей писали. Не пиши, пусть потомится.","Галя есть Галя. На её балконе бинокль — у меня окно. Двор поделен по-честному.","Про Галю плохого не скажу. Хорошего тоже — она прочитать может.","Галя и я — двор под присмотром с двух сторон. Машинам деваться некуда."],"ded":["Мой? Мой на лавочке. «Москвич» у него с девяносто восьмого. Не сломался — обиделся.","Мой передаёт привет. Он сказал, что сам бы так выехал. Я сказала: выезжай. Он сказал — сегодня поздно.","Про моего спрашиваешь? Хороший. Познакомились у гаража, бампер к бамперу. Так и живём — в одном ряду.","Мой прочитал твоё письмо. Сказал «толковый». Это у него высшая похвала, мне он такого не говорил.","Мой сорок лет обещает научить меня водить. Пока учит только словами. Слов у него много.","Мой в гараже. Говорит, чинит. Я говорю: «Москвич» уже сам за тебя всё понял."],"barsik":["Барсик в порядке. Спит на капоте «Волги». Хозяин «Волги» думает, что машина его. Барсик думает иначе.","Барсику твоё письмо понравилось: он на нём полежал. Это у него вместо подписи.","Барсик ничей, но кормлю его я. Значит, немножко мой. Он с этим не согласен, но ест.","Привет Барсику передала. Он посмотрел на меня так, будто и так знал.","Барсик гуляет по капотам — у него свой маршрут. Как у Мусоровоза, только тише.","Барсик здоров, сыт и важен. Важнее только участковый, и то по праздникам."],"recipe":["Пирожки с капустой — это к тёте Вале. Я только ем и записываю, у кого лучше. У неё лучше. Не говори ей.","Рецепт простой: тесто, капуста, терпение. Терпения больше всего — как во дворе с «Икарусом».","Рецепт мой не дам — секрет с восемьдесят третьего. Скажу одно: соль я кладу на глаз. Глаз у меня зоркий.","Варенье — смородиновое, сахара пополам. Банку с печатью видел на моих справках? Вот от неё.","Блины — по выходным. Первый блин отдаю Барсику. Он не ест, но ценит.","Тётя Валя рецепт не даёт даже мне. Я тридцать лет пытаюсь. Пока выведала только, что «с любовью»."],"other":["Письмо получила, прочитала внимательно. Записала в тетрадку. Спасибо, что пишешь.","Спасибо за весточку. Двор передаёт привет, и я тоже. Заходи — гостинец ждёт.","Прочитала. Подумала. Записала. Вот так у нас во дворе отвечают на всё важное.","Хорошо, что написал. Я письма храню в коробке из-под конфет. Конфеты мой съел ещё в девяностые.","Ответ короткий, но от души: рада тебе. Приходи во двор, там поговорим.","Твоё письмо лежит у меня на столе. Мой спрашивает, чего я улыбаюсь. Не скажу."]},"ps":["P.S. Положила тебе в ящик леденец. Он с прошлого года, но леденцы не портятся. Как я.","P.S. Положила тебе запасной ключ на десять от Толика. Он ещё не заметил.","P.S. Положила тебе место на лавочке. Пока я сижу на нём сама — чтобы не заняли.","P.S. Положила тебе в тетрадку закладку. Теперь у тебя своя страница — не потеряешь.","P.S. Положила тебе пирожок от тёти Вали. Половину. Вторую половину проверял мой.","P.S. Положила тебе открытку с «Волгой». Хозяин «Волги» не знает, что я её сфотографировала.","P.S. Положила тебе Барсика. Шучу. Барсик сам себя кладёт, куда хочет.","P.S. Положила тебе гостинец заранее. Если завтра придёшь — будет ещё один. Математика двора.","P.S. Положила тебе в ящик носовой платок. Это не намёк. Это на всякий случай — двор впереди сложный.","P.S. Положила тебе банку варенья. Пустую — варенье завтра, банку надо было освободить.","P.S. Положила тебе одну свою звёздочку из тетрадки. У меня их много: я ставлю их всем, кто без аварий.","P.S. Положила тебе пропуск во двор. Он недействительный, но очень красивый.","P.S. Положила тебе семечки. Для лавочки. Без семечек на лавочке не сидят — так не принято.","P.S. Положила тебе запасную метлу. Михалыч её искал. Не говори ему.","P.S. Положила тебе свою старую фотографию с «Победой». Я там молодая, а «Победа» — такая же.","P.S. Положила тебе газету «Вести со двора». Там про тебя ничего нет. Пока.","P.S. Положила тебе перо голубя. Отдел разведки передаёт: всё спокойно.","P.S. Положила тебе кусочек мела. Нарисуй себе стоянку, куда захочешь. Кроме клумбы.","P.S. Положила тебе домино Митяя, одну костяшку — «пусто-пусто». Он без неё теперь не выиграет. Пусть отдохнёт.","P.S. Положила тебе запасной гостинец. Его я берегла для Гали, но Галя не пишет.","P.S. Положила тебе карамельку «Гусиные лапки». Мой их прячет за батареей. Я знаю где.","P.S. Положила тебе в ящик тишину. Её во дворе мало, но тебе — не жалко.","P.S. Положила тебе бантик с ёлки. Ёлка ещё не скоро, а бантик уже есть. Я заранее.","P.S. Положила тебе свой карандаш. Тетрадку записывать. Ручку не дам — ручка у меня одна.","P.S. Положила тебе в ящик привет от всего подъезда. Он лёгкий, но его много."],"lichno":[["Здравствуй, {name}! Это Шура. Твоё письмо я прочитала сама, без очков и в очках.","Вот так. Обнимаю, как могу, — через домофон. Твоя баба Шура."],["{name}, доброе утро. Письмо твоё я отложила отдельно — такие не в общую коробку.","Записала тебя в тетрадку, двумя чертами. Баба Шура."],["Здравствуй, дорогой {name}. Отвечаю лично, не по шаблону, — мой засвидетельствует.","Береги себя. Двор тебя ждёт. Старшая по двору А. Ш."],["{name}, получила твоё письмо и сразу села писать. Даже чайник не поставила.","Ну вот, теперь чайник. Приходи во двор. Шура."],["Дорогой {name}! Письмо твоё прочитала на лавочке. Мой слушал и кивал — это у него редкость.","Пиши ещё, я всегда отвечаю. Твоя Шура и мой (кивает)."],["Здравствуй, {name}. Такое письмо раз в год бывает, я сразу поняла.","Спасибо тебе за него. Печать ставлю от души. Баба Шура."],["{name}, это Шура. Пишу от руки, как раньше, — твоё письмо того стоит.","Вот, всё сказала. Остальное — при встрече на лавочке."],["Здравствуй, {name}! Твоё письмо зачитывать не буду — это только тебе.","Обнимаю. Гостинец завтра будет особенный. Шура."],["{name}, доброе утро. Ответ задержался — я его переписывала три раза, чтоб красиво.","Вот, начисто. С уважением, первая квартира."],["Здравствуй, {name}. Отвечаю тебе не из тетрадки, а от себя.","Двор на месте, я на месте. Приходи. Твоя баба Шура."]]},"week":{"open":["Тише, лавочка! На этой неделе пишет {name} из {city}. Мой, сними кепку.","Письмо недели. Пишет {name} из {city}. Михалыч, метлу поставь, это надолго.","Зачитываю. {name}, город {city}. Галя, не перебивай — это не тебе.","Внимание, двор. Пришло письмо от {name} из {city}. Барсик, сядь ровно.","На этой неделе нам пишет {name} из {city}. Почерк хороший — значит, человек хороший. Проверено.","Письмо недели! {name}, {city}. Я его уже три раза прочитала, теперь ваша очередь слушать.","Митяй, домино потом. Пишет {name} из {city}. Это поважнее «рыбы».","Зачитываю с разрешения автора. {name} из {city}. Без разрешения я бы тоже зачитала, но с ним — приятнее.","Лавочка, внимание. {name} из {city} пишет. Валерка, не записывай на телефон — я и так всё запомню за тебя.","Письмо недели от {name}. Из {city}. Далеко. Но двор у нас один на всех — почта доходит."],"close":["Лавочка помолчала. Мой сказал: «Толково». Второй раз за год.","Тётя Валя прослезилась и пошла ставить пирожки. Это у неё вместо аплодисментов.","Михалыч сказал: «Вот это я понимаю». И подмёл то место, где стоял, — от уважения.","Галя сказала, что ей тоже есть что написать. Пишет уже третий год.","Митяй сказал, что в семьдесят восьмом так тоже писали. Но короче и про домино.","Валерка спросил, можно ли ответить. Можно. Только без «лол» — я не знаю, что это.","Барсик встал, потянулся и ушёл. Это у него высшая оценка: дослушал.","Толик сказал, что письмо собрано правильно: лишних слов всего три.","Двор зааплодировал. Голуби взлетели. Голуби у нас всегда аплодируют крыльями.","Я письмо сложила и убрала в коробку «лучшее». Коробка из-под конфет, конфеты мой съел в девяносто шестом."],"none":["На этой неделе писем нет. Лавочка расстроилась. Мой предложил прочитать свой кроссворд. Отказались.","Писем нет. Зачитываю тогда объявление про собрание. Лавочка резко вспомнила про дела.","Почта пустая. Значит, у всех всё хорошо. Или ящик опять Михалыч закрыл метлой.","Писем на этой неделе не пришло. Напиши ты — будешь первым. Первым у нас почёт.","Нет писем. Я перечитала прошлое. Лавочка слушала, как в первый раз. Двор у нас благодарный."]},"stage":{"names":[["Новенький","Newcomer"],["Жилец","Resident"],["Свой","One of us"],["Актив двора","Yard committee"],["Правая рука","Right hand"]],"up":[["Записала тебя в тетрадку. Пока карандашом — вдруг ты тут проездом.","Новенький! Сейчас все из окон посмотрят. Помаши. Не им — мне.","Добро пожаловать. Правило у двора одно: я всё вижу. Остальное — по ходу."],["Три дня ходишь — переписываю ручкой. Ты теперь жилец. Поздравляю, теперь на собрании и тебя спросят.","Жилец! Михалыч кивнул тебе. Это у него как грамота.","Всё, ты жилец. Галя спросила, кто такой. Я сказала — наш. Она расстроилась, значит, правильно сказала."],["Неделя! Ты теперь свой. Своим я говорю, где Галя ставит «Оку». Поперёк.","Свой. Это значит, если ты задержишься — я начну волноваться. Так что не задерживайся.","Ты свой. Мой разрешил садиться на его край лавочки. Это не каждому. Я сорок лет жду.","Свой! Табличку тебе повесили. Не трогай — Михалыч её два часа выравнивал."],["Две недели. Ты теперь актив двора. Будешь со мной на собраниях. Не бойся — говорю всё равно я.","Актив двора! Тебе положен голос на собрании. Мне — два, я старшая.","Актив! Толик сказал, что подпустит тебя к своему «Москвичу». Только смотреть.","Ты актив. Значит, если что-то во дворе не так — спрашивать будут с тебя. Это почёт. Отвечать буду я."],["Месяц. Ты моя правая рука. Ключ от подъезда не дам. Но домофон ты теперь знаешь — это я.","Правая рука! Мой ревнует. Он был правой рукой с восемьдесят третьего — но левой.","Правая рука двора. Теперь, если я в санатории, двор за тобой. Я не еду в санаторий. Но вдруг.","Ну всё, ты наш навсегда. В тетрадке у тебя своя глава. Я её начинаю словами «он пришёл и остался»."]],"thing":[["Скамеечка «для новеньких»","Маленькая. Вырастешь — пересядешь на большую лавочку."],["Почтовый ящик с твоим именем","Ключ от него у тебя. Запасной — у меня. Я не открываю. Я проверяю, закрыт ли."],["Табличка «Место {name}»","Место у клумбы. Сторожит Барсик — бесплатно, за капот."],["Место на лавочке рядом с бабой Шурой","Мой подвинулся. Не сразу и с комментариями."],["Свой ключ от шлагбаума","Единственный у двора, кроме Михалыча. Михалыч свой потерял в девяносто девятом."]],"page":["{date}. {name} вывел {car}. Без единой царапины. Подозрительно.","{date}. {name} прошёл двор {lv}. Галя видела. Делает вид, что нет.","{date}. {name} вывел {n} машин. Михалыч мести не успевал. Записала — за обоих.","{date}. {name} пропустил Скорую. Петровна просила передать: «Хороший человек». Записала дословно.","{date}. {name} в {lv}-м дворе думал долго. Я тоже. Додумали одновременно.","{date}. {name} вывел {col} {car}. Хозяин не узнал свою машину — сказал, что она никогда так красиво не уезжала.","{date}. {name} заходил {days}-й день. Барсик лёг на его место заранее.","{date}. Двор {lv}. {name} стукнул {car}. «Это не авария, — сказал мой, — это знакомство».","{date}. {name} прошёл задание дня. Я сказала соседкам — первым. Это почти правда, я не проверяла.","{date}. {name} освободил регион {reg}. Регион пустой, все разъехались. Скучаю по нему немного.","{date}. {name} вывел «Икарус». Записала с восклицательным знаком. Второй раз за тетрадку.","{date}. {name} прошёл двор {best}. Самый трудный у нас. Двор просил передать: «Ещё увидимся».","{date}. {name} взял подсказку. Подсказка была от меня. Записала в графу «помогала». Графа полная.","{date}. {name} не пришёл. Записала: «Наверное, дела». Ниже — «Пришёл. Дела, значит, хорошие».","{date}. {name} вывел {car} ночью. Свет в окнах зажёгся у троих. Я не считаюсь — я не гасила.","{date}. {name} прошёл двор {lv} с третьей попытки. Двор сдался красиво. Хвалю обоих.","{date}. {name} за день вывел {n} машин. Мой за день вывел себя на лавочку. Тоже достижение.","{date}. {name} поставил машину во двор. Теперь у него своя строка в учёте. Как у всех порядочных.","{date}. {name} написал мне письмо. Положила в коробку «лучшее». Коробка тяжелеет.","{date}. {name} — {days} дней во дворе. Переписала его со страницы «новенькие» на страницу «наши». Это навсегда."]},"title":[{"id":"newbie","t":["Новенький","Newcomer"],"when":"первая победа","s":"Записала тебя в тетрадку. Карандашом. Ручкой — после третьего двора."},{"id":"tenant","t":["Жилец","Resident"],"when":"3 дня захода","s":"Третий день ходишь. Галя уже спрашивала, с какого ты этажа. Я сказала — с моего."},{"id":"own","t":["Свой","One of us"],"when":"7 дней захода","s":"Неделя. Теперь, если что, ты тоже свидетель. Это не награда, это должность."},{"id":"aktiv","t":["Актив двора","Yard committee"],"when":"14 дней захода","s":"Две недели! Выдвигаю тебя в актив. Актив — это я. Теперь нас двое."},{"id":"right","t":["Правая рука","Right hand"],"when":"30 дней захода","s":"Ключ от подъезда не дам. Но домофон ты теперь знаешь — это я."},{"id":"night","t":["Ночной сторож","Night watchman"],"when":"10 дворов ночью","s":"Ночью двор твой, днём — мой. Договорились. Мой просил передать, что ночью он спит."},{"id":"early","t":["Ранняя пташка","Early bird"],"when":"10 дворов утром","s":"Раньше тебя во дворе встаю только я. И голуби. Голуби — по моей просьбе."},{"id":"clean","t":["Ни царапины","Not a scratch"],"when":"20 дворов без аварий","s":"Двадцать дворов без аварий. Мне на собрании рассказывать нечего. Буду рассказывать про тебя."},{"id":"nohint","t":["Сам с усам","Did it myself"],"when":"20 дворов без подсказок","s":"Двадцать дворов без подсказок. Мой без моих подсказок даже ботинки не находит."},{"id":"stars","t":["Отличник двора","Top of the yard"],"when":"30 дворов на три звезды","s":"Тридцать раз три звезды. Валерка спросил, можно ли списать. Я сказала — двор не тетрадь."},{"id":"streak5","t":["Без перекура","No smoke break"],"when":"5 побед подряд без поражения","s":"Пять подряд! Толик говорит, так не бывает. Толик пять подряд только болтов теряет."},{"id":"streak10","t":["Не остановить","Unstoppable"],"when":"10 побед подряд","s":"Десять подряд. Я тетрадку перевернула — думала, не той стороной пишу."},{"id":"tow","t":["Друг эвакуатора","Tow truck’s friend"],"when":"10 раз вызвал эвакуатор","s":"Эвакуаторщик про тебя спрашивал. Сказал — с тобой ему спокойнее. Ему за выезд платят."},{"id":"amb","t":["Зелёный коридор","Green corridor"],"when":"10 раз пропустил скорую вовремя","s":"Скорую десять раз пропустил. Петровна теперь болеет только по твоим дням."},{"id":"gran","t":["Кавалер","Gentleman"],"when":"10 дворов с бабушкой на переходе","s":"Клаву десять раз пропустил. Клава сказала, что ты воспитанный. Она уже и шляпку поменяла."},{"id":"oka","t":["Гроза «Оки»","Oka hunter"],"when":"10 раз вывел «Оку»","s":"Десятый раз выводишь «Оку». Галя думает, это личное. Пусть думает."},{"id":"volga","t":["Друг «Волги»","Volga’s friend"],"when":"20 раз вывел «Волгу»","s":"«Волгу» двадцать раз вывел и ни разу не задел. Хозяин хотел тебя обнять. Я не дала — он в мастике."},{"id":"bus","t":["Повелитель гармошки","Master of the bendy bus"],"when":"10 раз вывел «Икарус»","s":"«Икарус» десять раз. У нас его раньше всем подъездом разворачивали. Подъезд теперь без дела."},{"id":"album10","t":["Знаток","Car buff"],"when":"10 машин в альбоме","s":"Десять машин в альбоме. Мой столько знает, но только по звуку — и все «стучат»."},{"id":"album30","t":["Ходячий справочник","Walking catalogue"],"when":"30 машин в альбоме","s":"Тридцать машин знаешь. Толик к тебе за советом придёт. Сделай вид, что не знаешь — ему приятно."},{"id":"gift7","t":["Любимый гость","Favourite guest"],"when":"7 гостинцев взято","s":"Седьмой гостинец. Я в фартуке теперь отдельный карман держу — твой."},{"id":"gift30","t":["Свой человек на кухне","Kitchen regular"],"when":"30 гостинцев взято","s":"Тридцать гостинцев. Пироги я теперь считаю на одного больше. Мой думает, что это ему."},{"id":"daily7","t":["Дежурный","On duty"],"when":"7 заданий дня","s":"Семь заданий дня. Теперь ты дежурный. Дежурный — это кому я звоню первому."},{"id":"daily30","t":["Старший дежурный","Senior on duty"],"when":"30 заданий дня","s":"Тридцать заданий дня. Повышаю. Звонить теперь буду первому и чаще."},{"id":"reg1","t":["Почётный жилец","Honoured resident"],"when":"пройден первый регион","s":"Весь район вывел. Пишу на доске объявлений. Ниже Галиного объявления — но крупнее."},{"id":"reg5","t":["Путешественник","Traveller"],"when":"пройдено 5 регионов","s":"Пять регионов! Я говорю — ты в командировке. Галя говорит — в бегах. Мы не разговариваем."},{"id":"world","t":["Гражданин мира","Citizen of the world"],"when":"пройден регион «Вокруг света»","s":"Даже за границей дворы освободил. Там тоже бабушки на лавочках. Конкурентки."},{"id":"boss","t":["Укротитель дворов","Yard tamer"],"when":"5 боссов пройдено","s":"Пять трудных дворов взял. Михалыч сказал: «Талант». Михалыч так говорит только про метлу."},{"id":"y100","t":["Сотня","A hundred"],"when":"100 дворов пройдено","s":"Сто дворов. В моей тетрадке под тебя закончилась страница. Начинаю том второй."},{"id":"y500","t":["Легенда подъезда","Legend of the block"],"when":"500 дворов пройдено","s":"Пятьсот дворов. Про тебя уже рассказывают в соседнем дворе. Неправильно, но с уважением."}],"ntf":{"miss1":["Двор опять заставили. Я никого не пускала — сами заехали. Выручай.","Вчера тебя не было. Я твою клеточку в тетрадке не зачеркнула. Пока.","Михалыч: двор подметён. Можно заставлять — я для того и мёл.","Машины встали как попало. Хозяева говорят — это «по-новому». Покажи им по-старому.","Дед Митяй: домино расставлено. Играю пока сам с собой — и проигрываю. Выручай.","Валерка: я придумал, как выехать из трудного двора. Но не скажу, пока не придёшь.","Сегодня без тебя тихо. Слишком тихо. Мой даже проснулся проверить.","Толик: заходил к тебе в гараж — а тебя нет. Ключ на десять скучает."],"miss3":["Тебя три дня не было. Я всем сказала, что ты в санатории. Выгляди отдохнувшим.","Галя говорит, ты больше не придёшь. Приходи — пусть ей будет неловко.","Толик: «Москвич» три дня не заводил — ждал, когда ты придёшь посмотреть.","Три дня тишины. Мой уже решил, что двор теперь его. Он ошибается, но тихо.","Барсик третий день сидит на твоём месте у клумбы. Делает вид, что так и было.","Михалыч: три дня никто не выезжал. Я даже соскучился ворчать.","Мой: третий день Шура на лавочке одна. То есть со мной. А это, говорит, не считается."],"miss7":["Тебя неделю нет. Барсик спит на твоём месте у клумбы и делает вид, что так всегда было.","Неделю не видела. В тетрадке пишу «уехал по делам». Карандашом — сотру, как придёшь.","Мой: Шура неделю ни на кого не ворчит. Приходи, а то она на меня переключилась.","Неделя прошла. Двор заставили так, что даже Галя не выезжает. Ей полезно, а другим нет.","Толик: неделю никто в гараж не заглядывал. Я перебрал табурет. Дважды.","Я пирожок неделю держу. Он уже не пирожок, а сухарь. Но твой."],"gift":["Гостинец второй день лежит у меня в фартуке. Фартук начинает считать его своим.","Гостинец готов. Мой два раза спрашивал, кому. Два раза сказала — не тебе.","Держу тебе гостинец. Галя спросила, что там. Не скажу — пусть мучается.","Гостинец ждёт. Я его от Барсика прячу, а он от меня — уже нет.","Сегодня гостинец не простой. Какой — не скажу, а то придёшь только за ним. Хотя приходи.","Гостинец на лавочке. Михалыч обещал не подметать его до твоего прихода.","Мой: Шура велела передать — гостинец ждёт. А мне не дала даже понюхать."],"daily":["Двор дня — один на всех. Никто ещё не прошёл. Я никому не говорила, что ты придёшь.","Задание дня готово. Толик пробовал. Сказал, что у него руль не с той стороны.","Валерка: задание дня — трудное. Я посчитал ходы. Два раза. Получилось по-разному.","Двор дня ждёт. Скажу соседям, что ты пройдёшь первым. Про своих я всегда так говорю.","Сегодня двор дня с подвохом. Подвох я видела — синий, на «Ниве».","Дед Митяй: задание дня — как в семьдесят восьмом. Только машин больше. И я старше.","Михалыч: двор дня подмёл. Теперь его надо освободить, а то зря мёл."],"repair":["Толик: твоя машина готова. Я на ней уже сам немножко покатался — для проверки.","Толик: принимай работу. Лишних деталей осталось всего три. Значит, собрал правильно.","Толик: машина как новая. Ну, как новая моя. Моей двадцать лет.","Толик: готово к утру, как обещал. Утро у меня, правда, в два часа дня.","Толик: покрасил, собрал, завёл. Завелась с первого раза — я даже обиделся.","Толик: забирай. А то я к ней привыкну, и «Москвич» начнёт ревновать.","Толик: машина готова. Стоит в гараже, моргает фарами. Это она по тебе."],"streak":["Пятый день подряд! Мой столько раз подряд только в гараж ходит — «работать».","Неделю каждый день. Я тебя в тетрадке на отдельную страницу переписала. Красивым почерком.","Серия не прерывается. Галя считает, что это я тебе помогаю. Я ей не мешаю так считать.","Михалыч: ты ходишь, как я на работу. Только ты по своей воле.","Сегодня десятый день. Голуби прилетают раньше меня — тебя ждут."],"serial":["Новая серия у подъезда! Вчера Кузьмич чуть не продал «Москвич». Чуть — это важно.","Что было вчера в третьем подъезде — по телефону не скажу. Приходи на лавочку.","Сегодня новая серия. Галя уже знает. Узнай раньше, чем она перескажет неправильно.","Валерка: я знаю, чем кончится серия! Но мне никто не верит, а тебе поверят.","Продолжение есть. Я сама удивилась. Думала, после вчерашнего им всем неловко."],"mail":["Ответила на твоё письмо. Прочитала два раза: в очках и без. Ответ один.","Ответ лежит в почтовом ящике. Мой хотел прочитать первым. Я ящик заклеила.","Ответ готов. Писала ночью, мой не мешал — спал громко.","На письмо ответила. Не всё поняла, но ответила на всё.","Твоё письмо прочитано. Мой спросил, от кого. Сказала — по работе.","Валерка: баба Шура тебе ответила! Я не читал. Только первую строчку. И последнюю."],"read":["Твоё письмо зачитала на лавочке. Слушали все. Даже Барсик не ушёл, а он обычно уходит.","Зачитала твоё письмо соседям. Митяй сказал «толково». От Митяя это как медаль.","Тебя зачитали! Галя потом спросила, кто ты. Я сказала — наш.","Письмо твоё на лавочке прочитали. Мой даже проснулся. На второй половине.","Зачитала твоё письмо. Михалыч оперся на метлу и дослушал. Такого с 2003-го не было."],"rumor":["Говорят, ты вчера двадцать машин вывел. Галя говорит — сорок. Приходи, разберёмся.","Про тебя спрашивали из соседнего двора. Я сказала — родственник. Не подведи родню.","Во дворе рассказывают, что ты «Икарус» задом выводишь. Я не спорю — пусть растёт.","Слух про тебя дошёл до гаражей. Толик добавил своё. Теперь ты у них инженер.","Митяй всем говорит, что научил тебя он. Приходи, пока он не начал брать за это деньги."],"week":["Собрание жильцов в среду. Повестка: кто опять встал поперёк. Галя, это не намёк.","Двор недели выбран. Голосовали все. Победил тот, за кого голосовала я.","Неделя кончается. Подъезд отстаёт от плана. План — мой. Выручай подъезд.","Итоги недели на доске. Ты там есть. Галя тоже — но мельче.","На собрании решали, что чиним дальше. Твой голос ещё не учтён. Учту, как придёшь.","Субботник в выходные. Метлы раздаёт Михалыч. Тебе — машины, они тяжелее."],"night":["Двор на ночь поставлен. Утром всех выпускать. Не проспи — я не просплю.","Машины спят. Утром разбудим. Я — тетрадкой, ты — как умеешь.","Михалыч: двор встал на ночь как попало. Утром разберёшься — я подметать не успею.","Ночью в двор заехал КамАЗ. Как — никто не видел. Даже я. Утром выручай.","Утро! Все хотят на работу, а стоят в два ряда. Начинай с «Волги» — она дольше просыпается.","Ночью встали впритык. Утром удивляться будут ко мне, а выезжать — к тебе."]},"note":[["Вы задели мою машину. Ничего страшного, я её тоже иногда задеваю. Об гараж.","Хозяин синей «Шестёрки»"],["Царапина ваша? Оставьте себе. У меня их и так коллекция.","Хозяин «Копейки», кв. 14"],["Спасибо, что стукнули именно в эту дверь. Она всё равно не открывалась. Теперь открывается.","Владелец «Москвича»"],["Не переживайте. Моя жена этот бампер помяла сильнее. И записку не оставила — оставила мне машину.","Сосед с «Волгой»"],["Вмятину не трогайте, я её узнаю. Это та, что была. Вы просто поправили.","«Запорожец», третий подъезд"],["Машина не обиделась. Обиделся я. Но я отходчивый — до вечера.","Хозяин «Нивы»"],["Если будете ещё бить — бейте слева. Справа я уже покрасил.","Толик (машина не моя, но я в курсе)"],["Записываю номер вашего двора. На память. Зла не держу, держу тетрадку.","Баба Шура (передала хозяину)"],["Простите, что моя машина стояла там, где вы ехали. Она у меня такая — любопытная.","Хозяйка «Оки»"],["Удар был мягкий. Как в молодости, когда мы с женой знакомились у гаража.","Хозяин «Победы»"],["Оставляю вам яблоко. За беспокойство. Вмятину оставляю себе.","Дачник с «Буханкой»"],["Не волнуйтесь. «Икарус» и не такое видел. Он в восемьдесят пятом с трамваем бодался.","Водитель «Икаруса»"],["Мой «Каблук» стерпит всё. Он двадцать лет возит капусту — капуста страшнее.","Хозяин «Каблука»"],["Бампер погнулся в сторону прогресса. Теперь он смотрит в будущее.","Хозяин «Девятки»"],["Вы мне зеркало развернули. Теперь я вижу себя. Давно не видел. Похудел.","Хозяин «Газели»"],["Ничего. Мусоровоз железный. И я железный. Только по утрам.","Водитель мусоровоза"],["На этой машине мой дед ездил, отец ездил, я езжу. Теперь и вы немножко поездили.","Хозяин «Волги с оленем»"],["Оставляю номер телефона. Звоните, если опять соскучитесь.","«Нива», 5-й этаж"],["Претензий нет. Есть вопрос: как вы туда въехали? Я пятнадцать лет не могу.","Хозяин «Шестёрки», кв. 9"],["Я вас прощаю. Но хозяйке не говорите — она не простит. Ей нравилась та фара.","Муж хозяйки «Оки»"],["Удар засчитан. Счёт 1:0 в пользу вашей машины. Реванш — в субботу.","Сосед с «Копейкой»"],["Не беспокойтесь. На этой «Волге» ещё ни одной царапины не было. Теперь будет о чём рассказать.","Хозяин «Волги»"],["Вы задели мою «Ниву». Она проехала Алтай, Байкал и дорогу к нашей даче. Вы её не испугали.","Хозяин «Нивы»"],["Подкрашу сам. Цвет «морская волна». У меня остался с девяносто первого. С тех пор и ждал.","Хозяин «Москвича»"],["Спасибо, что не в клумбу. Клумбу мне Михалыч не простил бы. Машину — простит.","Хозяйка «Шестёрки»"],["Ничего. Мою машину задевают раз в год, как по часам. Вы как раз вовремя.","Таксист с первого этажа"],["Стукнули — значит, заметили. А то стоит, стоит — никто не смотрит.","Хозяин серой «Девятки»"],["Моя «Ока» маленькая, но гордая. Она вам ничего не скажет. Скажу я: ничего.","Хозяйка «Оки»"],["Буду вам благодарен, если в следующий раз вы приедете с Толиком. Он чинит, пока вы извиняетесь.","Хозяин «Газона»"],["Вмятину назову в вашу честь. У меня их уже девять. Ваша — самая красивая.","Хозяин «Москвича-412»"],["Не переживайте. ЗИМ видел войну, перестройку и моего сына за рулём. Вы — пустяк.","Хозяин ЗИМа"],["Я вас не ругаю. Ругает Шура. Но это у неё работа такая.","Хозяин «Волги»"],["Задели? Я и не заметил. Мне Шура сказала. Шура всегда замечает.","Хозяин «Копейки»"],["В следующий раз сигнальте. Я выйду, отодвинусь вручную. Мне не трудно, у меня «Ока».","Хозяйка «Оки»"],["На двери теперь вмятина в виде сердечка. Жена довольна. Оставлю.","Хозяин «Девятки»"],["Мою «Буханку» не помнёшь. Вы помяли — значит, вы сильный человек.","Хозяин «Буханки»"],["Просьба: если ещё раз задумаете — предупредите. Я уберу с крыши рассаду.","Хозяйка «Нивы»"],["Это ничего. Это даже кстати. Я давно хотел к Толику, а повода не было.","Хозяин «Жигулей»"],["Спасибо, что выбрали мою машину. Их тут сорок, а вы — мою.","Хозяин «Шестёрки», с юмором"],["Царапину видел. Претензий нет. Подписываю: «видел, не возражаю».","Михалыч (за хозяина, он на работе)"],["Я вам записку, а вы мне — привет хозяину «Волги». Он меня в прошлом году задел.","Хозяин «Москвича»"],["Всё нормально. «Запорожец» ушастый — он такое слышит заранее и уворачивается. Не успел.","Хозяин «Запорожца»"],["Удар принят. Машина в порядке. Магнитола заиграла. Двенадцать лет молчала.","Хозяин «Девятки»"],["Хозяина нет, он на даче. Записку пишет кот. Кот возражает.","За Барсика — баба Шура"],["Прощаю. Я сам так въезжал в девяносто восьмом. В тот же бампер.","Дед Митяй"],["Стукнулись — бывает. Главное, что не в «Победу». В «Победу» стучать нельзя, это история.","Хозяин «Нивы», сосед хозяина «Победы»"],["Вы задели мой молоковоз. Молоко не пострадало. Оно и так кислое.","Водитель молоковоза"],["Ничего страшного. У меня машина застрахована. Не на деньги — на терпение.","Хозяйка «Шестёрки»"],["Удар был лёгкий, как поцелуй. Только громче. Машина покраснела. Она и так красная.","Хозяин «Копейки»"],["Записку пишу на обороте квитанции за свет. Так что мы теперь оба при расходах.","Хозяин «Газели»"],["Дорогой водитель! Моя машина стоит здесь двадцать лет. Вы первый, кто её подвинул. Спасибо.","Хозяин «Москвича»"],["Задели ПАЗик — ничего. Он школьный, он и не такое слышал.","Водитель ПАЗика"],["Не волнуйтесь, на «Ниве» вмятины не видно. Она вся — одна сплошная вмятина. Это стиль.","Хозяин «Нивы»"],["Вы меня задели, а я вас — нет. Получается, я хорошо стою. Запишите это Шуре.","Хозяин серебристой «Волги»"],["Не извиняйтесь. Лучше научите меня так выезжать. Я свою третий день вывести не могу.","Хозяин «Газели» (застрял)"],["Машину помяли. Зато я познакомился с соседом. Сосед — это вы. Приятно.","Новосёл из 34-й"],["Удар был. Я сначала испугался, потом понял, что это не моя. Потом понял, что моя.","Хозяин «Копейки», растерянный"],["Моя «Чайка» видела министров. Вы — первый, кто её стукнул. Министры бы не посмели.","Хозяин «Чайки»"],["Не беда. У меня на этот случай есть шпатлёвка и Толик. Шпатлёвка надёжнее.","Хозяин «Москвича»"],["Вы стукнули мою «Волгу». Сейчас я её помою. Тридцать лет мою — и тут повод.","Хозяин «Волги»"],["Дорогой сосед! Буду рад, если в следующий раз вы просто постучите в окно.","Хозяин «Девятки», 2-й этаж"],["Претензий не имею. Имею предложение: давайте поставим машины по очереди. Я — первый.","Хозяин «Шестёрки»"],["Удар записан в журнал. У меня журнал как у Шуры, только тоньше.","Хозяин «Таблетки»"],["Ничего. Пожарная машина крепкая. Мы на ней и не в такое въезжали. По работе.","Пожарный с третьего"],["Это уже вторая вмятина за неделю. Первая — моя. Теперь у машины пара.","Хозяин «Оки»"],["Записку пишу левой рукой, правой держу кофе. Вы испортили только почерк.","Хозяин такси"],["Машина не моя, я её сторожу. Сторожил. Сейчас ещё постерегу — для порядка.","Сторож гаражей"],["Не стоит беспокойства. «Каблук» привычный. Его у магазина каждый день тележками обижают.","Хозяин «Каблука»"],["Вы оставили на моей машине след. Я оставлю его на память. Как у Шуры — тетрадку.","Хозяин «Нивы»"],["Уважаемый! Мою машину нельзя задевать по вторникам. Сегодня среда. Всё в порядке.","Хозяйка «Шестёрки»"],["Удар был что надо. Толик сказал, что машина даже лучше стала. Толик врёт, но приятно.","Хозяин «Москвича»"],["Вы задели мою «Буханку». Она пахнет хлебом. Теперь пахнет хлебом и неловкостью.","Хозяин хлебного фургона"],["Это не страшно. В автобусе всё равно никого не было. Только я. Я цел.","Водитель ЛиАЗа"],["Ну и правильно. Давно пора было эту фару поменять. Я всё ждал, кто решится.","Хозяин «Волги»"],["Ваша машина поцарапала мою. Моя — вашу. Предлагаю ничью и чай.","Хозяин «Девятки»"],["Вмятина маленькая. Как вы. Шучу. Вы молодец, все так ездят.","Хозяйка «Оки»"],["Мой «Горбатый» такое уже пережил. Он у меня ветеран. Вы ему — ещё одна история.","Хозяин «Горбатого»"],["Спасибо, что разбудили. Я в машине спал. Опаздываю на работу. Уже нет.","Хозяин «Газели»"],["Не переживайте. Я сам задел вашу, когда парковался. Так что мы квиты, просто вы не знали.","Хозяин «Шестёрки», честно"],["Задели? Ой. А я радовался, что встал удачно.","Хозяин «Копейки»"],["Записку оставляю под дворником. Дворник у меня не работает. Записка хоть делом займётся.","Хозяин «Москвича»"],["Вы меня толкнули — и машина завелась. Третий день не заводилась. Спасибо от души.","Хозяин «Запорожца»"],["Не извиняйтесь. На стоянке стукаются все. Но вы — первый, кто сделал это красиво.","Сосед с балкона"],["У меня трактор. Ему всё равно. Мне — тоже. Хорошего дня.","Хозяин «Беларуса»"],["Дорогой водитель, вы помяли капот. Барсик теперь спит в вмятине. Ему удобно. Спасибо.","Хозяин «Волги»"],["Не страшно. Мою «Таблетку» лечили и не от такого.","Фельдшер с «Таблеткой»"],["Ничего страшного. Я эту машину продаю. Теперь со скидкой. Вы не хотите?","Кузьмич"],["Вмятину не выправляйте. Это теперь у меня отличительная черта. Как родинка.","Хозяйка «Девятки»"],["Удар засчитан. Подписи: я, жена, Шура. Шура — свидетель, она всегда свидетель.","Хозяин «Шестёрки»"],["Мою «Шишигу» не возьмёшь. Вы бампер свой проверьте — у неё он с зубами.","Хозяин «Шишиги»"],["Вы задели КамАЗ. Это как задеть дом. Дом в порядке. Как вы?","Водитель КамАЗа"],["Прощаю. Сегодня у меня день рождения, я всех прощаю. Завтра — по обстоятельствам.","Хозяин «Нивы»"],["Ничего. Мне машину из ремонта всё равно забирать некому — пусть ещё постоит у Толика.","Хозяин «Копейки»"],["Записка от машины: «Мне не больно. Хозяину — немножко. Хозяйке — очень. Она ругается».","«Ока», вежливая"],["Спасибо, что не в мусоровоз. Его потом не отмоешь. Вас — тоже.","Водитель мусоровоза"],["Вы стукнули автокран. Автокран ничего не почувствовал. Я тоже — я на обеде.","Крановщик"],["Не переживайте. Мороженое не растаяло. Оно и не такое выдерживало — у нас холодильник.","Мороженщик"],["Вмятину вижу. Вас не вижу. Сделаю вид, что это ветер. Ветер у нас сильный.","Хозяин «Волги», философ"],["Если что — я в 12-й. Не к Гале, а напротив. Галя тут ни при чём.","Хозяин «Москвича»"],["Машину помяли — и ладно. Мне её всё равно Шура запрещала тут ставить.","Хозяин серой «Девятки»"]],"forecast":{"kopeyka":["Первой — «Копейка». День простой и надёжный: всё заведётся с первого раза. Мой — с третьего.","«Копейка» с утра — значит, день по-старому: без спешки, зато всё на месте. Даже Михалыч."],"volga":["Утро началось с «Волги» — день плавный, торжественный. Никуда не торопимся, но все расступаются.","«Волга» первая — к важным делам. Мой уже надел пиджак. Сидит в нём на лавочке."],"zapor":["«Запорожец» с утра — день весёлый, громкий и немножко с ушами. Слушать будут все.","Первым — «Запорожец». День будет маленький, но гордый. Как его хозяин после выезда."],"oka":["Первая — «Ока». День небольшой, аккуратный. Главное — не потерять его среди больших.","«Ока» с утра — к сюрпризам: сперва не заметишь, а потом окажется, что это главное за день."],"niva":["«Нива» первая — день пройдёт везде. Даже там, где Михалыч не чистил.","Утро с «Нивы» — к дальней дороге. Хоть до магазина, но с лопатой и термосом."],"buhanka":["«Буханка» с утра — день сытный и с запасом. Хлеба не обещаю, но настроение будет.","Первой — «Буханка». День будет квадратный, зато просторный: все поместятся."],"ikarus":["«Икарус» первым — день длинный, с поворотами. На поворотах держись, он гнётся — и ты гнись.","Утро с «Икаруса» — к большой компании. Весь подъезд выйдет помогать. Советами."],"musorovoz":["Мусоровоз первым — день начнётся с уборки. Зато к обеду будет чисто и в голове, и во дворе.","Мусоровоз с утра — к переменам. Всё лишнее уедет. Галя, к сожалению, останется."],"pobeda":["Первая — «Победа». День, сами понимаете, удачный. Название обязывает.","«Победа» с утра — к хорошим воспоминаниям. Мой вспомнил загс. Я вспомнила, что он опоздал."],"morozh":["Мороженое первым — день сладкий, детский. Михалыч будет ворчать с пломбиром в руке.","Утро с мороженщика — к радости. Валерка уже стоит у подъезда. С шести утра."],"kamaz":["КамАЗ первым — день тяжёлый, но всё вывезет. Главное — не стоять у него на пути.","КамАЗ с утра — к большим делам. Мелкие он не замечает. Как и бордюр."],"taxi":["Такси первым — день быстрый. Все куда-то едут, а платить никто не хочет.","Утро с такси — к поездке. Мой собрался. Пятнадцать лет собирается, а тут — такси."]},"car_type":[{"id":"volga","t":"Ты — «Волга»","s":"Ездишь медленно, торжественно и почти без аварий.","w":"Тебя не водят — тебя выгуливают. Двор встаёт, когда ты выезжаешь."},{"id":"kopeyka","t":"Ты — «Копейка»","s":"Надёжно, просто, каждый день понемногу.","w":"Заводишься с первого раза. Мой — с третьего. Я знаю, о чём говорю."},{"id":"zapor","t":"Ты — «Запорожец»","s":"Смело, шумно, с первой попытки и наугад.","w":"Сначала едешь, потом думаешь. Иногда — наоборот, и тогда совсем хорошо."},{"id":"oka","t":"Ты — «Ока»","s":"Быстрые дворы, мало ходов, тихо.","w":"Тебя сперва не замечают. А потом двор пустой и все спрашивают, кто это был."},{"id":"niva","t":"Ты — «Нива»","s":"Берёшь трудные дворы и боссов, не боишься помех.","w":"Пройдёшь везде. Даже там, где Михалыч не чистил с прошлой зимы."},{"id":"ikarus","t":"Ты — «Икарус»","s":"Большие дворы, длинные серии выездов.","w":"Длинный путь, много поворотов. Весь подъезд провожает. Половина — советами."},{"id":"skoraya","t":"Ты — «Скорая»","s":"Быстро, много выездов подряд, скорую пропускаешь вовремя.","w":"Ты всегда успеваешь. Петровна теперь болеет по твоему расписанию."},{"id":"taxi","t":"Ты — «Такси»","s":"Заходишь часто и ненадолго.","w":"Приехал, вывез, уехал. Мой так в гараж ходит — только у тебя толк есть."},{"id":"buhanka","t":"Ты — «Буханка»","s":"Собираешь гостинцы, сундуки, всё про запас.","w":"У тебя всё с собой и всего с запасом. Хлеба нет, но это мелочи."},{"id":"musorovoz","t":"Ты — «Мусоровоз»","s":"Пользуешься эвакуатором и подсказками без стеснения.","w":"Всё лишнее увозишь, не раздумывая. Двор после тебя — как после субботника."},{"id":"pobeda","t":"Ты — «Победа»","s":"Много звёзд, задания дня каждый день.","w":"Название обязывает, и ты обязываешься. Я тебя в тетрадку пишу с большой буквы."},{"id":"morozh","t":"Ты — «Мороженое»","s":"Играешь вечером и ночью, с удовольствием.","w":"Тебя ждут. Не знаю, за что — но ждут, как пломбир в июле."}],"bl":{"petrovich":["Петрович с речки пришёл, с уловом. Загляните к нему — он рассказывает, пока рыба не кончится.","Петрович принёс леща. Говорит, «вот такой». Руки у Петровича длинные.","Пеку пироги с рыбой. Рыбу заказала у Петровича. Петрович обещал. Петрович всегда обещает.","Петрович опять на машине на рыбалку. Машина ловит лучше: она хоть стоит тихо.","Петрович привёз карася и историю про щуку. Карася — мне, щуку — всему двору.","Мне на пироги нужно три окуня. Петрович обещал пять. Значит, будет один и рассказ.","Петрович выехал на рассвете. Вернулся к обеду, довольный. Рыбы нет, зато какое утро.","Видела Петровича с удочками. Если вывезешь его «Ниву» — с меня пирог, с него — окунь. Наверное."],"skip":["Этот двор упрямый. Оставь его — вернёшься позже, а он к тому времени подобреет.","Не мучайся. Я этот двор в тетрадке подчеркну — потом вместе разберём.","Пропусти пока. Мой свой «Москвич» с девяносто восьмого «пропускает» — и ничего, живём.","Двор никуда не денется. В этом-то и беда — но сегодня это нам на руку. Дальше пойдём.","Пусть постоит. Машины во дворе стоят — это их работа. А у тебя работа — ехать дальше.","Отложим. Я сорок лет так собрание откладываю — и каждый раз оно проходит лучше."],"glasses":["Это что, «Икарус»? А, это «Ока» близко стоит. Я сегодня без очков.","Красная «Копейка» поехала! Или это пожарная? Без очков у меня все красные — «Копейки».","Кто это там, Михалыч? А, это метла к машине прислонена. Тоже хорошо.","«Волга» выехала! Ну или «Буханка». Что-то большое и важное — запишу как «Волгу».","Очки забыла. Сегодня в тетрадку пишу крупно. Получилось три машины на страницу.","Это Барсик на капоте? А, это шапка Митяя. Митяй, иди забери шапку.","Без очков двор кажется пустым. Красота. Жаль, что это не так.","Мусоровоз уехал! Ой, нет, это Толик в комбинезоне. Толик, извини.","Вижу «Победу». Мой говорит — «Москвич». Мой тоже без очков. Записываем «Победу» — красивее.","Без очков я всех узнаю по звуку. Вот это — «Запорожец». Или Валерка на велосипеде.","Кто так встал? Не вижу. Значит, Галя. Без очков у меня всегда Галя.","Синяя или зелёная? Без очков — бирюзовая. В тетрадке будет бирюзовая. Хозяин удивится.","Шесть машин или восемь? Пусть будет семь. Я сегодня добрая и без очков.","«Ока» выехала. Или жук. Если жук — он молодец, ровно пошёл.","Очки нашла! Они были на мне. Мой видел и молчал с утра. Записываю."],"navi":[["Навигатор: «Через сто метров поверните направо».","Шура: «Через сто метров там клумба. Направо — это к Михалычу на разговор»."],["Навигатор: «Вы прибыли к месту назначения».","Шура: «Ты прибыл ко мне на лавочку. Это я назначила»."],["Навигатор: «Маршрут перестроен».","Шура: «Маршрут у нас один, с восемьдесят третьего. Это ты перестроился»."],["Навигатор: «Держитесь левее».","Шура: «Левее — Галина «Ока». От неё держись правее»."],["Навигатор: «Впереди затруднение движения».","Шура: «Впереди Клава в новой шляпке. Это не затруднение, это показ»."],["Навигатор: «Развернитесь, когда это будет возможно».","Шура: «У нас это возможно раз в год, когда КамАЗ уезжает»."],["Навигатор: «Съезд через двести метров».","Шура: «Двор у нас шестьдесят метров. Она из какого двора говорит?»"],["Навигатор: «Двигайтесь прямо».","Шура: «Прямо — гаражи. Там Толик. Если хочешь к Толику — двигайся»."],["Навигатор: «Нет сигнала».","Шура: «Зато есть я. Я сигнал с восемьдесят третьего»."],["Навигатор: «Время в пути — две минуты».","Шура: «Это без собрания. С собранием — до вечера»."],["Навигатор: «Вы отклонились от маршрута».","Шура: «Он не отклонился. Он объезжает Барсика. Барсик лёг поперёк»."],["Навигатор: «Повторяю: поверните направо».","Шура: «Женщина, не повторяйте. Я сорок лет повторяю — не помогает»."]],"bday":{"open":["Сегодня у бабы Шуры день рождения. Сколько лет — не скажет. Скажет, сколько стоит во дворе машин.","У бабы Шуры праздник! Двор украшен шариками. Шарики на ниточке — чтобы никто не припарковался.","День рождения Шуры! Мой подарил цветы с клумбы. Михалыч ищет, кто сорвал."],"wish":["Чтобы двор всегда был пустой, а лавочка — полная.","Чтобы все парковались ровно. Хотя бы в ваш день рождения.","Здоровья, как у «Волги», и характера, как у «Нивы».","Чтобы Галина «Ока» наконец встала вдоль.","Новую тетрадку — потолще. Чтобы всех записать.","Чтобы мой сам выкатил «Москвич». Хотя бы к юбилею.","Чтобы голуби слушались, а Барсик — хотя бы делал вид.","Тёплую лавочку и холодный квас.","Чтобы Михалыч подметал, а не прислонял метлу.","Чтобы все машины выезжали с первого раза. И мой — тоже.","Пусть каждое утро начинается с тишины. А потом — с нас.","Чтобы на собрании все приходили. И уходили, когда вы скажете.","Чтобы Толик собрал всё без лишних деталей. Ну хотя бы с двумя.","Чтобы пироги удавались, а соседи — заходили на пироги.","Самого внимательного свидетеля в городе — вам. Хотя вы и так он.","Чтобы Клава ходила по переходу, когда никто не едет. Шучу — пусть ходит, мы подождём.","Чтобы двор помнил вас так же, как вы — каждую машину в нём.","Чтобы в тетрадке была страница «хорошие» — и на ней все.","Пусть Валерка вырастет и сам повезёт вас на дачу.","Чтобы домофон звонил только по хорошему поводу.","Отпуска от двора. Хотя бы на воскресенье. Мы покараулим.","Чтобы гостинцев хватало на всех, а на вас — с горкой.","Сто лет на лавочке! И чтобы лавочка выдержала.","Чтобы ни одной царапины ни у машин, ни у вас.","Чтобы мусоровоз приезжал вовремя. Ну, это уже чудо, но вдруг.","Чтобы в вашем дворе всегда было солнце. Даже в полярную ночь.","Спасибо, что вы за всеми смотрите. С днём рождения!","Пусть мой подарит не цветы с клумбы, а с рынка.","Чтобы Митяй хоть раз проиграл в домино. Не вам — себе.","Будьте всегда старшей по двору. Младшей — не надо, у нас Валерка."],"total":["Шуре пришло {n} пожеланий. Она прочитала все. Два раза. Вслух — моему.","{n} пожеланий за день! Шура записала их в тетрадку. На отдельную страницу «хорошие».","Итог: {n} пожеланий, один торт и ни одной аварии. Лучший праздник с восемьдесят третьего."]},"newbie34":["В 34-ю кто-то въехал. Машина новая, шторы старые. Выясняю.","Новосёл из 34-й поставил машину на моё место. Он ещё не знает, что место моё. Узнает к вечеру.","Новосёл здоровается со всеми. Подозрительно. Записала: «вежливый, проверить».","Выяснила про новосёла: работает, не шумит, машину моет. Галя не верит, что такие бывают.","Новосёл спросил у Михалыча, где тут парковка. Михалыч смеётся до сих пор.","Новосёл принёс мне торт. Я его не подкупаю, он сам. Записала в «хорошие» — авансом.","Новосёл в 34-й выехал с первого раза. Я три раза посмотрела. Понравилось.","Мой пошёл знакомиться с новосёлом. Вернулся через три часа. Говорит — про машины.","Новосёл спросил, кто у нас главный. Мне сказали. Я подтвердила.","Новосёл прижился. Сегодня встал поперёк — значит, свой."],"overheard":["Кто-то из соседнего двора вчера вывел {n} машин и ни разу не стукнулся. Галя не верит.","Говорят, в каком-то дворе вчера прошли «Час пик» за минуту. Я записала, но с вопросом.","Слышала: кто-то десятый день подряд приходит. Как ты. Но ты — наш.","Во дворе через дорогу кто-то вывел «Икарус» без подсказок. Мой сказал, что он тоже может.","Подслушала у гаражей: кто-то прошёл задание дня первым. Толик ставил на тебя.","Говорят, кто-то вчера пропустил скорую {n} раз. Петровна передаёт ему привет.","Соседки шепчутся: кто-то прошёл {n} дворов за вечер. Ужин, говорят, остыл.","Из третьего подъезда сказали: кто-то вывел «Волгу», не коснувшись. Хозяин «Волги» плакал.","Голуби с соседнего двора рассказывают: там один водитель ночью выезжает тише кота.","Слух: где-то есть водитель, у которого {n} машин в альбоме. Я сказала — у нас будет больше.","Говорят, кто-то в другом городе прошёл двор с бабушкой на переходе и бабушка помахала.","Митяй узнал на рынке: кто-то вывел {n} машин подряд без аварий. Митяй торговался, не верил.","Подслушала: кто-то вчера звал соседа на помощь, и сосед помог. Хорошие люди ещё есть.","Говорят, есть двор, где все встали ровно. Не верю. Поеду проверю — с тетрадкой.","Кто-то из Владивостока прошёл двор раньше всех. У них утро раньше. Нечестно, но молодец."],"miss":["«Мисс двора»! Какая краше: голубая «Шестёрка» или вишнёвая «Нива»? Хозяева не спят — ждут.","Конкурс красоты! Две машины, обе только из покраски. Толик голосует за обе — он красил.","Голосуем: кто краше? Победительнице — место у клумбы на неделю. Проигравшей — у мусорки.","«Мисс двора» выбрана! Хозяин проигравшей сказал, что его машина «скромная». Скромно стоит поперёк.","Какая краше? Я бы выбрала, но я в жюри. Жюри в нашем дворе — это я.","Мисс двора недели — сиреневая «Ока». Галя сказала, что подкупили. Я не знаю, кто бы мог.","Конкурс красоты машин. Мой голосует за «Москвич». «Москвича» в конкурсе нет. Мой упорный.","Итоги «Мисс двора»: победила вишнёвая. Синяя тоже красивая, просто вишнёвая чаще моется."],"bet":["Мы с Галей поспорили: ты выведешь весь двор без аварий. Галя ставит пирог. Я тоже — свой.","Пари: Шура против Гали. Ставка — кто моет лестницу. Не подведи, я не люблю мыть.","Галя говорит, в этом дворе «Икарус» не развернуть. Я говорю — ты развернёшь. Двор смотрит.","Спор двора: за неделю выведем тысячу машин. Галя смеётся. Пусть смеётся, пока считает.","Поспорили с Галей на её балкон. Если выиграю — неделю смотрю оттуда. Обзор лучше.","Пари проиграно. Пеку Гале пирог. С капустой. Она не любит капусту. Я помню.","Галя спорит, что ты не придёшь завтра. Я спорю, что придёшь. Ставка — честь подъезда.","Выиграла! Галя моет лестницу. Сама видела — с первого по пятый. Записала в тетрадку.","Весь двор на твоей стороне. Даже Барсик. Барсик, правда, на стороне того, у кого колбаса.","Пари: успеешь пропустить скорую — Галя признаёт, что у нас двор лучше. Вслух."],"number":["Номер недели — {no}. Увидишь машину с этим номером — выводи. Приз у меня в фартуке.","На этой неделе ищем номер {no}. Знаю, где он стоит. Не скажу. Ищи — так интереснее.","Номер {no} нашёлся! Приз твой, честно заработанный. Галя спросила, можно ли ей. Нельзя.","Объявляю номер недели: {no}. Записала крупно. Мой уже ищет. У себя в гараже.","Номер {no} где-то во дворах. Михалыч видел, но был с метлой — не запомнил.","Вывел номер {no}? Держи приз. Обещала — значит, даю. Я слово держу, как тетрадку.","Номер недели — {no}. Валерка выучил наизусть. Теперь говорит его вместо «здравствуйте».","Ищем {no}. Подсказка: машина синяя. Или зелёная. Я была без очков."],"gai":["Свисток! Это из кустов. Товарищ инспектор, мы тут своих выпускаем. Идите к Гале.","Гаишник в кустах. Сидит с шестого утра. Я тоже с шести — но я на лавочке, как человек.","Инспектор свистнул. Я сказала: водитель наш, документы у меня в тетрадке. Он ушёл.","Свистнули? Это не нам. Это Барсику — он перебегает где хочет.","Товарищ инспектор, не свистите. У нас двор, а не стадион. И тут мой спит.","Из кустов свисток. Я ответила в свой. У меня тоже свисток есть, с восемьдесят третьего.","Инспектор хотел оштрафовать. Я показала протоколы за сорок лет. Он решил, что лучше в кусты.","Гаишник вышел из кустов, посмотрел, как ты выезжаешь, и ушёл обратно. Видно, учиться."],"combo8":["Восемь подряд! Двор поёт. Михалыч приплясывает с метлой — я всё записала.","Восьмая нота! Даже мой проснулся и спросил, кто играет. Это ты играешь — машинами.","Восемь подряд — как песня. Мой подпевает. Не в такт, но от души.","Вот это серия! Голуби встали в ряд — слушают.","Восемь машин — и ни одной фальшивой ноты. В нашем дворе это впервые."],"kortezh":["Пять одного цвета подряд — это же свадьба! Бросаю рис. Голуби счастливы больше всех.","Кортеж! Я плачу. Не потому что свадьба, а потому что впервые ровно поехали.","Свадебный кортеж! Жених — «Нива», невеста — «Шестёрка». Родители против, но поздно.","Пять подряд одного цвета! Мой вспомнил нашу свадьбу. Там машина была одна, и та чужая.","Кортеж выезжает! Рис кончился, кидаю пшено. Голуби аплодируют.","Кортеж со двора! Михалыч снял кепку. Последний раз снимал, когда метлу новую выдали."],"scold":["Разбор ночи. «Волга» встала на два места. Хозяин говорит, она широкая. Она не широкая, она важная.","Кто встал у подъезда? Записано: зелёная «Нива», 23:14. Хозяин спал уже в 23:15. Быстро.","Ночью встали так, будто играли в тетрис. Проиграли все.","«Газель» поперёк. Водитель объяснил — «так короче». Короче — это для него, не для двора.","Кто-то поставил «Оку» между двумя машинами. Хозяин «Оки» не знает, как. Я — тоже. Красиво.","Ночная парковка — как наш подъезд на собрании: все пришли, никто не сел ровно.","«Москвич» моего стоит на месте с девяносто восьмого. Единственный, кто встал правильно.","Мусоровоз ночевал у нас. Кто пустил — неизвестно. Утром узнаем, кому он мешает. Всем.","«Копейка» встала задом к клумбе. Я не ругаю. Я записываю. Это хуже.","Ночью въехал «Икарус». Водитель сказал — к маме. Мама в 7-й. «Икарус» — во всём дворе.","Такси ждало пассажира всю ночь. Пассажир — Митяй. Он вызвал и пошёл спать.","Две «Девятки» встали нос к носу. Как будто поругались. Утром — мириться, и по очереди.","Хозяин «Буханки» сказал, что встал «на минутку». Минутка длилась до утра. Я засекала.","Кто встал на газон — признавайтесь. Михалыч уже признался: он метлу на газоне оставил.","Ночью было тихо, но парковались громко. Мой проснулся три раза. Ему полезно.","КамАЗ встал как дома. Дома у него, видимо, двор втрое шире.","Шлагбаум стоял открытый, и все решили, что это приглашение. Это был Михалыч с ведром.","Встали ровно только две машины. Обе — потому что заглохли.","Ночная смена во дворе: все приехали, все устали, все встали как попало. Утром — разбираемся.","Кто ставил машину в темноте — тому спасибо за творчество. Утром будет трудно, но интересно."],"repaint":["Перекраска! Толик пробовал новый пульверизатор. Машины меняют цвет, а Толик — адрес.","Внимание: машины меняют цвет! Это не я без очков. Это правда. Записываю как есть.","Перекраска во дворе. Хозяин «Волги» не узнал свою. Узнал по запаху мастики.","Цвета пляшут. Михалыч сказал, что это осень. Михалыч всегда так говорит.","Двор перекрашивается каждые три касания. Я трижды переписала в тетрадке, чья машина чья."]},"deep":{"arch":{"hi":[["Арка у нас узкая, по одной проезжают. Не толпитесь!","Our arch is narrow — one at a time. No crowding!"],["Через арку — как в собес: по очереди и с бумажкой.","Through the arch — like at the benefits office: in turn, with your papers."],["Арку ещё при Хрущёве строили, на «Запорожец» с запасом.","The arch was built under Khrushchev — sized for a Zaporozhets, with room to spare."]],"full":[["Арка забита! Пусти сначала тех, кто в переулок.","The arch is jammed! Let the side-street cars go first."],["Куда ж ты в арку, там уже трое стоят!","Where are you going? Three are already queuing in the arch!"],["Пробка в арке! Как в девяностых за колбасой.","A jam in the arch! Like the sausage queues in the nineties."]],"lose":[["Арка забита — двор встал. Не гони всех к арке подряд: пусти сначала тех, кто едет в переулок.","The arch is jammed — the yard is stuck. Don’t send everyone to the arch in a row: let the side-street cars go in between."],["Встали в арке, как пробка в бутылке. Переулочных береги на конец!","Stuck in the arch like a cork in a bottle. Save the side-street cars for the end!"]]},"draw":{"hi":[["Такси у нас с характером: куда покажешь, туда и поедет.","Our taxi has a mind of its own: it goes where you point."],["Таксист дорогу не знает — нарисуй ему, он не обидится.","The cabbie doesn’t know the way — draw it for him, he won’t mind."]],"go":[["Ишь, таксист! Дворами поехал.","Look at that cabbie — cutting through the yards!"],["Счётчик тикает, а он круги нарезает. Молодец!","The meter’s running and he’s doing laps. Good lad!"],["Вот это маршрут! В навигаторе такого нет.","Now that’s a route! Not in any satnav."]]},"rest":{"hi":[["Отдохни, милок. Тут одной кнопкой: нажал — и вся колонна поехала. Задумаешься — свистну.","Have a rest, dear. One tap here: press — and the whole column goes. If you dawdle, I’ll whistle."]],"wh":[["Фьють! Разъезжайтесь, голубчики!","Wheet! Off you go, my dears!"],["Фьють-фьють! Это я не тебе, это машинам.","Wheet-wheet! Not you — the cars."],["Свисток у меня ещё с пионерлагеря. Работает!","I’ve had this whistle since summer camp. Still works!"]],"win":[["Вот и славно. Чайку бы теперь — и снова во двор.","Lovely. A cup of tea now — and back to the yard."],["Отдохнул? Вот и я посидела. Пойдём дальше машины гонять.","Rested? I had a sit too. Let’s go chase cars again."]]},"replay":{"pre":[["Так, смотрим повтор. Вот он едет, ни о чём не думает…","Right, let’s watch the replay. Here he goes, not a care in the world…"],["Повтор, как по телевизору. Михалыч, неси очки!","A replay, just like on TV. Mikhalych, bring my glasses!"],["Замедленно смотрим. Как в «Спортлото», только без выигрыша.","Slow motion. Like the lottery draw, but nobody wins."]],"crash":[["Бабах! Вот тут-то голубчик и не посмотрел.","Bang! That’s where the dear forgot to look."],["Ой-ой-ой! Прямо в бок. Я аж пирожок выронила.","Oh-oh-oh! Right in the side. I dropped my pie."],["Вот! Вот этот момент! Стрелку видел? Не видел.","There! That moment! Did you see the arrow? You didn’t."]],"after":[["Ничего, железо выправят. А ты теперь знаешь, кого пускать первым.","No harm, the metal will straighten out. And now you know who goes first."],["Разбор полётов окончен. Ещё разок — и двор твой.","Debrief over. One more go and the yard is yours."]]},"clip":{"a":[["Смотри, как двор пустеет…","Watch the yard empty out…"]],"b":[["Пусто! Хоть бельё развешивай.","Empty! You could hang out the washing."],["Красота! Пять секунд — и тишина.","Beautiful! Five seconds — and silence."]]},"zhezl":{"use":[["Регулировщик из тебя что надо! Палочкой — и поехал.","You’d make a fine traffic cop! One wave and off it goes."],["Жезл — сила! Мой покойный Петя в ГАИ так же махал.","The baton is power! My late Petya waved one just like that in the traffic police."]]},"push":{"use":[["Толкнули дружно — и пошла родимая!","One good shove — and off she rolls!"],["Раз-два, взяли! Как «Москвич» зимой заводили.","One-two, heave! Like starting the Moskvich in winter."]]}},"money":{"pie":[["С капустой! Угадал. Теперь ты мне как внук.","Cabbage pies! You guessed. You’re like a grandson to me now."],["Ой, с яйцом и луком… Ты где ж такой вежливый вырос?","Oh, egg and onion… Where did you learn such manners?"],["Пирожки взяла. Твою машину теперь ставлю у самого подъезда.","Got the pies. Your car now parks right by my door."],["Михалыч учуял — уже идёт с чайником. Делиться не буду.","Mikhalych smelled them — he’s coming with a kettle. Not sharing."],["Тёплые ещё! Запишу тебя в тетрадку. В хорошую графу.","Still warm! I’ll write you in my notebook. In the good column."]],"lavka":[["Свои люди — свои цены. Бери, не стесняйся.","Neighbours get neighbour prices. Help yourself."],["Ларёк открыт, пока я на лавочке. А я на лавочке всегда.","The kiosk is open while I’m on the bench. I’m always on the bench."],["Тут всё честно: не понравится — пожалуйся мне же.","All honest here: don’t like it — complain to me."]],"parcel":[["Дед с утра по гаражам собрал. Открывай — только сначала реклама, у нас всё по-честному.","Grandpa put this together in the garages. Open it — an ad first, we’re honest here."],["Опять посылка от деда. Внутри, говорит, «самое нужное». В прошлый раз был гвоздь.","Another parcel from grandpa. “The essentials,” he says. Last time it was a nail."],["Дед завернул в «Правду» за восемьдесят шестой. Газету не выбрасывай.","Grandpa wrapped it in a 1986 newspaper. Don’t throw that away."]],"vyr":[["Держись, выручу! Жизнь, подсказка и эвакуатор — всё сразу.","Hang on, I’ll rescue you! A life, a hint and a tow truck — all at once."],["Толик уже бежит с тросом. Я — с советом.","Tolik’s running with a tow rope. I’m coming with advice."]]},"quarter":{"themes":{"sob":{"t":["Собрание жильцов","Residents’ meeting"],"s":["Повестка: что чиним в первую очередь? Итоги — в воскресенье.","Agenda: what do we fix first? Results on Sunday."],"o":[["Лавочку","The bench"],["Фонарь у арки","The arch lamp"],["Песочницу","The sandpit"],["Шлагбаум","The barrier"]]},"gal":{"t":["Переворот: Галя хочет в старшие","A coup: Galya wants to run the yard"],"s":["Галя из 12-й собирает подписи. Я, конечно, не волнуюсь. Совсем.","Galya from No. 12 is collecting signatures. I’m not worried. At all."],"o":[["Шура остаётся","Shura stays"],["Пусть Галя попробует","Let Galya try"]]},"par":{"t":["Пари Шуры с Галей","Shura’s bet with Galya"],"s":["Шура спорит: квартал выведем до пятницы. Галя — что не выведем. Ты за кого?","Shura bets we clear the quarter by Friday. Galya bets we won’t. Whose side?"],"o":[["За Шуру","Shura"],["За Галю","Galya"]]},"miss":{"t":["Мисс двора","Miss Yard"],"s":["Выбираем самую красивую машину двора. По краске. Галя за свою не голосует — ей нельзя.","Picking the yard’s prettiest car. By paint. Galya can’t vote for her own."],"o":[["Вишнёвая «Копейка»","Cherry Kopeyka"],["Белая «Волга»","White Volga"],["Голубой «Москвич»","Light-blue Moskvich"],["Жёлтое такси","Yellow taxi"]]},"cen":{"t":["Перепись машин двора","Yard car census"],"s":["Перепись! Какая машина у тебя во дворе главная? Михалыч считает, я записываю.","Census! Which car rules your yard? Mikhalych counts, I write it down."],"o":[["Жигули","Zhiguli"],["Москвич","Moskvich"],["Волга","Volga"],["Нива","Niva"]]}},"sud_t":[["Товарищеский суд","Comrades’ court"]],"sud":[{"s":["Кто-то ставит машину поперёк двух мест. Говорит — «так красивее».","Someone parks across two spaces. Says it “looks nicer”."],"o":[["Простить и подарить рулетку","Forgive, gift a tape measure"],["Неделю паркуется последним","Parks last for a week"]]},{"s":["Валерка из 3-й сигналит в шесть утра: «будильник у всех один».","Valerka from No. 3 honks at 6 a.m.: “one alarm for all”."],"o":[["Простить — он жаворонок","Forgive, he’s an early bird"],["Пусть чинит всем будильники","He fixes everyone’s clocks"]]},{"s":["Кто-то моет «Волгу» из шланга Михалыча. Без спросу.","Someone washes a Volga with Mikhalych’s hose. Unasked."],"o":[["Простить, шланг общий","Forgive, the hose is shared"],["Пусть купит новый шланг","He buys a new hose"]]},{"s":["Голуби облюбовали «Москвич» Толика. Толик винит соседа сверху.","Pigeons love Tolik’s Moskvich. Tolik blames the upstairs neighbour."],"o":[["Голуби не виноваты","The pigeons are innocent"],["Сосед кормит — сосед и моет","He feeds them, he washes it"]]},{"s":["Митяй занял место у подъезда ёлкой. В марте.","Mityai saved a spot by the door with a fir tree. In March."],"o":[["Простить, праздник долгий","Forgive, long holidays"],["Ёлку — во двор, всем","The tree goes to the yard"]]},{"s":["Кто-то написал мелом «тут стою я». Без подписи.","Someone chalked “I park here”. No name."],"o":[["Простить — смешно","Forgive, it’s funny"],["Стереть и встать самим","Erase it and park there"]]},{"s":["Галя повесила на арку объявление про своих кошек. Три листа.","Galya posted three pages about her cats on the arch."],"o":[["Оставить, кошки красивые","Keep it, nice cats"],["Один лист, не больше","One page, max"]]},{"s":["Сосед из 7-й прогревает «Ниву» по сорок минут.","The neighbour from No. 7 warms up his Niva for 40 minutes."],"o":[["Простить — зима","Forgive, it’s winter"],["Прогревать у гаражей","Warm it up by the garages"]]},{"s":["Кто-то утащил лавочку к своему подъезду. Сидит один.","Someone dragged the bench to his door. Sits alone."],"o":[["Простить, пусть сидит","Forgive, let him sit"],["Лавку — на место","Bench goes back"]]},{"s":["У «Запорожца» Петровича третий месяц нет колеса. Стоит на кирпичах.","Petrovich’s Zaporozhets has stood on bricks for three months."],"o":[["Простить — ждёт деталь","Forgive, waiting for a part"],["Всем двором найти колесо","The yard finds a wheel"]]},{"s":["Кто-то паркуется на клумбе Шуры. Ромашки помяты.","Someone parks on Shura’s flowerbed. Daisies crushed."],"o":[["Простить, посадит новые","Forgive, he plants new ones"],["Неделю поливает клумбу","Waters the bed for a week"]]},{"s":["Таксист Лёша спит в машине у подъезда. Храпит в открытое окно.","Taxi driver Lyosha naps in his car by the door. Snores loudly."],"o":[["Простить — устал человек","Forgive, he’s tired"],["Подарить ему подушку и беруши","Gift him a pillow and earplugs"]]}],"chalk":[["Тут был Вася","Vasya was here"],["Сначала синюю!","Blue one first!"],["Не торопись","Take it slow"],["Шура, мы тебя любим","We love you, Shura"],["Дед, держись!","Hang on, grandad!"],["Осторожно: Пазик","Watch out: bus"],["С угла начинай","Start from the corner"],["Я с третьего раза","Took me three tries"],["Классики ↓","Hopscotch ↓"],["Михалыч — лучший","Mikhalych rocks"],["Тут разворачивались","U-turn here"],["Галя, не сердись","Galya, don’t be cross"],["Москвич найдётся","The Moskvich will turn up"],["Двор чистый!","Yard is clear!"],["Привет из Твери","Hello from Tver"],["Сам в шоке","Even I’m shocked"],["Лёгкий двор","Easy one"],["Тяжёлый двор","Tough one"],["Начни с выезда","Start at the exit"],["Не трогай грузовик","Leave the truck"],["Мама, я водитель","Mum, I’m a driver"],["Тут стоял я","I parked here"],["Без аварий!","No crashes!"],["Субботник — в воскресенье","Clean-up on Sunday"],["Валерка, верни насос","Valerka, give back the pump"],["Здесь живёт кот","A cat lives here"],["Тише, дети спят","Quiet, kids asleep"],["Всем удачи","Good luck all"],["Сначала думай","Think first"],["Ура!","Hooray!"]],"country":[["По всей стране вчера вывели {y} дворов. Михалыч в газете прочитал — значит, правда.","Yesterday the whole country cleared {y} yards. Mikhalych read it in the paper, so it’s true."],["Вчера страна вывела {y} дворов. Галя говорит — больше. Галя всегда говорит больше.","Yesterday the country cleared {y} yards. Galya says more. Galya always says more."],["Михалыч звонил на радио: вчера по стране {y} дворов выведено. Его даже в эфир пустили.","Mikhalych called the radio: {y} yards cleared across the country yesterday. They put him on air."]]},"season":{"lesson":[["Урок первый. Инструктор сказал: «Зеркала». Я их протёрла. Оказалось, не то.","Lesson one. The instructor said “mirrors”. I polished them. Wrong answer."],["Урок второй. Тронулась плавно. Инструктор проснулся только на светофоре.","Lesson two. Smooth start. The instructor only woke up at the lights."],["Учусь парковаться задом. Задом у меня выходит всё, кроме парковки.","Learning to reverse-park. Everything goes backwards except the parking."],["Инструктор спросил, зачем я сигналю. Я поздоровалась с Галей. Два раза.","The instructor asked why I honked. I was greeting Galya. Twice."],["Сегодня «змейка». Конусы целы. Инструктор — частично.","Slalom today. The cones survived. The instructor — mostly."],["Мой говорит: «В мою молодость права покупали». Я ему: «В твою молодость и машины покупали — одну на подъезд».","Mine says licences used to be bought. I said cars used to be one per building."],["Горка. Ручник. Я. Горка победила, но я тоже не сдалась.","A hill start. Handbrake. Me. The hill won, but I didn’t give up."],["Инструктор научил меня смотреть в зеркало. Теперь я вижу, кто за мной паркуется неровно. Всех записала.","Now I see who parks crooked behind me. All noted."],["Ехала по городу. Сорок в час. Обогнал велосипедист. Вежливо.","Drove in town. Forty per hour. A cyclist overtook me. Politely."],["Учусь разворачиваться в три приёма. У меня пока в семь, но красиво.","Learning the three-point turn. I do it in seven, but beautifully."],["Ночная езда. Фары включила, дворники включила, радио включила. Поехали утром.","Night driving. Lights on, wipers on, radio on. We set off in the morning."],["Теория. Знаю все знаки. Один придумала сама — «Галя, не паркуйся». Не засчитали.","Theory. I know every sign. Invented one — “Galya, no parking”. Not accepted."],["Последний урок. Инструктор подарил мне свою ручку. Сказал: «Записывайте, у вас получается».","Last lesson. The instructor gave me his pen: “Keep notes, you’re good at it”."]],"oka":[["Моя «Ока» сегодня здесь. Учусь. Кто её зажмёт — запишу в тетрадку жирным.","My Oka’s in this yard today. I’m learning. Box her in and you’re in bold in my notebook."],["Видишь сиреневую «Оку»? Это я на уроке. Выпусти аккуратно — она не врезается, она обижается.","See the lilac Oka? That’s me in a lesson. Let her out gently — she doesn’t crash, she sulks."],["«Ока» на месте, инструктор на лавочке. Двор — экзаменационный. Не подведи.","Oka in place, instructor on the bench. This yard counts as an exam route."]],"exam":[["Экзамен! Галя купила иномарку и поставила поперёк. Говорит — случайно. Выпусти мою «Оку».","Exam day! Galya bought a foreign car and parked it across. ‘By accident’. Get my Oka out."],["Сдала! Инструктор сказал: «Без замечаний». Галя сказала: «Повезло». Записала обеих.","Passed! The instructor said ‘no remarks’. Galya said ‘lucky’. Noted them both."],["Не вышло с первого раза — это нормально. Я тоже пересдаю. Иномарка Гали никуда не денется.","Not first time — that’s fine. I’m retaking too. Galya’s car isn’t going anywhere."]],"chaika":[["В четверг с семи до восьми во двор заедет «Чайка». Настоящая. Кто зайдёт — запишет в альбом.","On Thursday 7–8 pm a real Chaika comes to the yard. Drop in and it goes in your album."],["«Чайка» приехала! Чёрная, длинная, блестит. Михалыч снял кепку. Записала в твой альбом.","The Chaika is here! Black, long, shiny. Mikhalych took his cap off. It’s in your album."],["«Чайка» уехала до следующего четверга. Кто не успел — не беда, она пунктуальная.","The Chaika has gone till next Thursday. Missed it? No matter — she’s punctual."]],"snow":[["Первый снег! У всех сразу. Первую машину откапывай — два касания: одно лопатой, одно — ласково.","First snow — for everyone at once! Dig out the first car: two taps, one with a shovel, one kindly."],["Откопали! Михалыч говорит, к обеду растает. Михалыч говорит так с ноября по март.","Dug out! Mikhalych says it’ll melt by lunch. He says that November to March."]],"mar8":[["Восьмое марта! Правило двора: пропусти даму. Машина с цветочком выезжает первой.","Women’s Day! Yard rule: ladies first. The car with a flower leaves first."],["Даму пропустили — как положено. Мой даже сам открыл ей ворота. Нарисованные.","The lady went first, as it should be. Mine even opened the gate for her. A painted one."],["Дама уехала не первой. Ничего, я сама в восемьдесят третьем никого не пропускала.","The lady didn’t go first. Never mind — in 1983 I didn’t let anyone pass either."]],"sep1":[["Первое сентября! Двор надо освободить до звонка — у детей линейка. Успеешь?","September 1st! Clear the yard before the school bell rings. Can you make it?"],["До звонка успели! Первоклашки прошли с букетами, ни одной машины на пути.","Made it before the bell! First-graders walked through with flowers, not a car in the way."],["Звонок уже был. Ничего — дети опоздали тоже. Традиция.","The bell has rung. Never mind — the kids were late too. Tradition."]],"bday":[["Шура, с днём рождения! Мы во дворе собрали пожелания — {n} штук. Читай вслух.","Happy birthday, Shura! We collected {n} wishes in the yard. Read them out."],["Пожелание записала. Положу в тетрадку, на самую первую страницу.","Wish noted. It goes on the very first page."]],"novosel":[["В 34-й зажёгся свет! Новосёл приехал с машиной — ищи её во дворах, она теперь наша.","A light in flat 34! The new neighbour came with a car — look for it in the yards, it’s ours now."]],"number":[["Нашёлся номер недели! Держи приз — честно заработал.","Found the number of the week! Here’s your prize."]],"evt":[["Две недели — новое дело двора: «{t}». Справимся — будет краска, какой ни у кого нет.","A new two-week yard task: “{t}”. Finish it for a paint nobody else has."],["Дело двора сделано! Краска твоя. В гараже, на полке. Не продаётся.","Yard task done! The paint is yours, in the garage. Not for sale."]],"bazar":[["Михалыч открыл ёлочный базар у гаражей. Говорит, ёлки свои. Лес не подтверждает.","Mikhalych opened a tree market by the garages. Says the trees are his own. The forest disagrees."],["Ёлку купили! Ставим во дворе — в «Уюте двора» она теперь своя.","Tree bought! It stands in the yard now — it’s in your Yard Comforts."]],"season":[["Новый сезон! На стене подъезда — новый календарь. Сериал сезона: «{t}».","New season! A fresh calendar on the stairwell wall. This season’s story: “{t}”."]],"card":[["Открытка из города {city}! Вешаю на холодильник. Холодильник уже не видно.","A postcard from {city}! On the fridge it goes. The fridge is disappearing."]]},"ux":{"tea":[["Обед. Чайник на подоконнике, Шура с кружкой. Машины подождут — у них тоже обед.","Lunch. Kettle on the sill, Shura with a mug. Cars can wait."],["Чай с баранками. Мой макает. Я не смотрю — сорок лет не смотрю.","Tea and bagels. My husband dunks. I don’t look. Forty years I don’t look."],["Обеденный перерыв во дворе. Даже Барсик лёг на капот — греется.","Lunch break in the yard. Even Barsik is on a bonnet, warming up."],["Пей чай, пока горячий. Двор не убежит — он заставленный.","Drink your tea while it’s hot. The yard won’t run away — it’s blocked in."]],"quiet":[["Тихий час. Шура дремлет. Выезжай без гудков — ★ тишины тебе.","Quiet hour. Shura’s napping. Drive out without honking — a star of silence."],["Ш-ш-ш. С двух до трёх двор спит. Кроме тебя и Барсика.","Shh. From two to three the yard sleeps. Except you and Barsik."],["Тихий час. Мой храпит на лавочке. Это не гудок, не пугайся.","Quiet hour. My husband’s snoring on the bench. That’s not a horn."]],"quietStar":[["Тихо выехал — молодец. Ставлю тебе звёздочку тишины. Отдельно, в тетрадку.","You left quietly — good. A star of silence, in my notebook."],["Ни одного стука. Звезда тишины. Мой так не умеет — он даже спит громко.","Not a single bump. Star of silence."]],"paper":[["Вечер. Мой читает газету. Третий раз ту же — говорит, «чтобы закрепить».","Evening. My husband reads the paper. Same one, third time."],["Зажглись окна. Сейчас все выглянут и скажут, кто как поставил.","Windows lit up. Everyone will look out now and judge the parking."],["Вечерняя газета: «Во дворе всё спокойно». Это я написала. Я и есть газета.","Evening paper: “All quiet in the yard.” I wrote it. I am the paper."],["Фонарь зажгли. Михалыч опять его пнул — иначе не горит.","The lamp’s on. Mikhalych kicked it again — it won’t light otherwise."]],"night":[["Ночь. Шура спит. На лавочке сидит Барсик и всех записывает.","Night. Shura’s asleep. Barsik sits on the bench and takes notes."],["Ночью лавочку сторожит Барсик. Взятки — сосисками.","At night Barsik guards the bench. Bribes in sausages."],["Тихо во дворе. Только Барсик и луна. И ты.","Quiet in the yard. Just Barsik, the moon, and you."]],"morning":[["Утро. Шура вышла с ведром — поливать клумбу и смотреть, кто как встал.","Morning. Shura’s out with a bucket — watering, and watching who parked how."],["С добрым утром! Двор проснулся, машины — нет.","Good morning! The yard woke up. The cars didn’t."]],"day":[["Шура на посту. Пост — это лавочка.","Shura is on duty. Duty means the bench."],["День как день. Галя опять поставила поперёк.","Just another day. Galya parked sideways again."]],"guest":[["petrovich","Петрович заходил с речки — ведро плотвы, сказки на час. Сказал, у них в «Рыбалке» тоже очередь — к лунке."],["petrovich","Петрович присел на лавочку. «У вас, — говорит, — машины. У нас — лещи. Тоже вытаскивать надо»."],["zina","Заходила Зина, учительница из соседнего двора. Проверила тетрадку. Поставила «пять». Мне — «четыре», за почерк."],["zina","Зина в гостях. Говорит: «Двор — это тоже слово. Из четырёх букв, и все заняты»."],["mityai","Митяй принёс домино. Играем на «рыбу». Рыбу Петрович принёс. Всё сходится."],["mihalych","Михалыч из соседнего двора — тот, что ведёт Викторину. Спросил, сколько машин у нас во дворе. Я сказала — все."]],"guestEn":[["Petrovich came by from the river. Says in his game there’s a queue too — at the ice hole."],["Zina the teacher dropped in. Checked my notebook. Gave me a B for handwriting."]],"note":["Под дворником записка. Положила в тетрадку — пачка растёт.","Записка от хозяина. Почерк сердитый, но вежливый. В тетрадку.","Опять записка. У нас во дворе так знакомятся — через бампер и бумажку."],"frank":[["Толик подобрал деталь после аварии. «Пригодится, — говорит. — Я из этого кое-что соберу»","Tolik picked up a part after the crash. “It’ll come in handy”"],["Ещё деталь в гараж № 7. Толик потирает руки. Мне страшно.","Another part for garage No. 7. Tolik rubs his hands. I’m scared."],["Деталь к Толику. Он считает: «Ещё немного — и оживёт!» Что оживёт — не говорит.","A part for Tolik. “Almost there — it’ll live!” What will — he won’t say."]],"frankDone":[["Толик собрал! Колёса от «Запора», кабина от «Буханки», гудок — от «Скорой». Записали в альбом как «Франкенштейн». Ездит. Боком.","Tolik built it! Zaporozhets wheels, Bukhanka cab, ambulance horn. Into the album as “Frankenstein”. It drives. Sideways."]],"hold":[["Держу тебе место у подъезда. Одно. Сумку поставила — никто не сядет.","I’m holding a spot for you by the entrance. One. My bag’s on it."],["Место за тобой. Галя пыталась — я на неё посмотрела.","The spot is yours. Galya tried — I gave her a look."]],"pie":[["Пирожок? С капустой! Ой, спасибо. Ты мне, я — тебе: место на лавочке.","A pie? Cabbage! Thank you. You for me, me for you — a seat on the bench."],["С картошкой! Мой любимый. Мой — в смысле муж — тоже хочет. Не дам.","Potato! My favourite. My husband wants one too. He won’t get it."]],"barsik":[["Где Барсик? Только что на капоте сидел. Найди — и выезжай.","Where’s Barsik? He was just on a bonnet. Find him, then drive."],["Барсик опять спрятался. Глянь, под какой машиной.","Barsik’s hiding again. Under which car?"]],"barsikOk":[["Нашёл! Барсик делает вид, что так и задумано.","Found him! Barsik acts like it was the plan."],["Вот он, хитрец. Иди, Барсик, на лавочку — там чай.","There he is. Off to the bench, Barsik."]],"barsikNo":[["Не там. Барсик под соседней — уже ушёл на лавочку.","Not there. He was under the next one — gone to the bench."]],"visitors":[["К тебе заходили {n} соседа. Посмотрели двор, сказали — «ничего так». От Гали это комплимент.","{n} neighbours visited your yard."]],"lettersWeek":[{"name":"Валентина","city":"Тверь","t":"Баба Шура, я тоже старшая по подъезду. Сорок квартир, двенадцать машин и один кот. Держимся."},{"name":"Николай Петрович","city":"Омск","t":"Прошёл двор с «Икарусом» с пятого раза. Жена сказала — как в жизни: сначала газуешь, потом думаешь."},{"name":"Людмила","city":"Самара","t":"Играю с внуком. Он быстрее, я аккуратнее. Счёт по звёздам — у меня."},{"name":"Сергей","city":"Красноярск","t":"Водитель автобуса тридцать лет. Ваши дворы — это мой маршрут утром. Только у вас разрешают выезжать."},{"name":"Галина","city":"Воронеж","t":"Не Галя, но тоже ставлю «Оку» поперёк. Простите. Исправлюсь. Наверное."},{"name":"Тамара","city":"Пермь","t":"Ваш муж молодец, что молчит. Мой тоже. Молчим вместе — через экран."},{"name":"Виктор","city":"Казань","t":"Собрал все «Волги» в альбоме. Где взять чёрную? Жена говорит — в мечтах."},{"name":"Анна","city":"Сочи","t":"У нас во дворе тоже все друг про друга записывают. Только не в тетрадку, а в чат дома."}],"nbHead":[["Тетрадка бабы Шуры","Granny Shura’s notebook"]],"nb":{"st":"{date}. Перевела в «{x}». Ручкой.","ps":"{date}. Положила в ящик P.S. — {x}.","note":"{date}. Записка под дворником. Пачка: {x}.","frank":"{date}. Толик собрал Франкенштейна № {x}. Ездит боком.","quiet":"{date}. Тихий час: выехал без единого стука.","car":"{date}. Какая ты машина: {x}. Похоже.","ct":"{date}. Какая ты машина — «{x}». Записала ручкой: похоже.","hold":"{date}. Держала место у подъезда.","pie":"{date}. Угостили пирожком. С {x}.","bars":"{date}. Нашёл Барсика.","zone":"{date}. Во дворе новое: {x}.","sub":"{date}. Субботник: {x}.","mail":"{date}. Пришло письмо. Ответила к утру.","week":"{date}. Зачитали письмо недели."},"zones":{"bench":["Лавочка","Bench"],"flowers":["Клумба","Flower bed"],"swing":["Качели","Swing"],"park":["Стоянка (+1 место в кармане)","Parking (+1 pocket spot)"],"pigeon":["Голубятня (голубь)","Dovecote (pigeon)"],"garage":["Гараж Толика (эвакуатор раз в день)","Tolik’s garage (one tow a day)"],"fountain":["Фонтанчик","Fountain"],"stage":["Сцена для собраний","Meeting stage"]},"g7Lead":[["Ранее в сериале «Гараж № 7»:","Previously on “Garage No. 7”:"]],"voiceOn":[["Шура заговорила вслух. Если громко — скажи, я тише.","Shura is speaking out loud now."]],"glass":[["Очки забыла, вот и рисую стрелки покрупнее. Чтоб и мне видно.","Forgot my glasses, so I draw the arrows bigger."]],"amb":[["Скорая к бабе Шуре! Давление. Выпусти её первой — остальные подождут.","Ambulance for Granny Shura! Let it out first."]],"ambOk":[["Спасибо, милок. Давление сто двадцать на восемьдесят — как у космонавта.","Thank you, dear. Blood pressure like an astronaut’s."]],"find":[["Три аварии подряд — Толик просит помочь найти поломку. Заглянешь?","Three crashes — Tolik asks you to help find the fault."]],"road":[["Новый город — на въезде дорожные работы. Толик говорит: «Объедем — я знаю как»","New town — roadworks at the entrance."]]},"en":{"scene":[{"id":"tetradka","t":"The notebook","l":[["valerka","Granny Shura, what are you always writing?"],["shura","Who parked where. Since 1983."],["valerka","But why?"],["shura","So 1984 has something to live up to."]]},{"id":"metla","t":"The broom","l":[["mihalych","Who parked on my lawn again?"],["shura","Noted: blue Lada, 7:42 a.m."],["mihalych","Whose?"],["shura","Yours, Mikhalych."],["mihalych","…I only leaned my broom on it."]]},{"id":"moskvich","t":"The Moskvich","l":[["ded","Shura, I could get out of there too."],["shura","You’ve been getting your Moskvich out since 1998."],["ded","I’m waiting for the yard to clear."],["shura","(points at the empty yard)"],["ded","…Bit late today, though."]]},{"id":"znakomstvo","t":"How we met","l":[["shura","Do you remember where we met?"],["ded","By the garages. You took down my number."],["shura","So romantic."],["ded","It was a parking ticket, Shura."]]},{"id":"navigator","t":"Satnav","l":[["valerka","I’ve got a satnav! “In 100 metres, turn left.”"],["shura","Left? That’s the flower bed."],["valerka","“Recalculating.”"],["shura","See? Everyone does that around me."]]}],"roman":["The Zaporozhets has fallen for the Volga. She parks by the door, he parks by the bins. Six metres and a world apart.","At night he flashed his headlight at her. Just the one — the other’s been out since spring. It came out as a wink.","Then a Lada Nine rolled in. Tinted windows, loud stereo. The Volga shivered in every panel. The Zaporozhets quietly stalled.","His best friend, Tolik’s old van, said: “Just be yourself.” He was himself. He didn’t start.","The Volga’s engine is playing up. He’d give her his. But his engine is in the back. Wouldn’t fit.","Minus thirty. Nobody starts. Except the Zaporozhets: he’s air-cooled. Frost is to him what a compliment is to the Volga.","The Volga started! Tolik says it’s the battery. I say it’s love. Tolik says: “Same thing.”","The Kopeyka learned: abroad is lovely, but the one who tows you home is the one parked next to you.","The yard emptied. In the middle: the Volga and the Zaporozhets, bumper to bumper. Like me and mine by the garages, fifty years ago.","Season finale. Sansanych grumbled: “That Zaporozhets is in my spot again.” And didn’t move it. I wrote: “married.”"],"intercom":{"hello":["It’s Shura. Don’t worry, it’s not business. Well, it is. It’s always business.","Morning, it’s Shura on the intercom. Cheaper than the phone, and the whole stairwell hears.","It’s Shura. I’m calling first, before Galya does. I saw her reaching for the button.","It’s Shura. I’ll be brief. My notebook has 48 pages, so — not that brief.","It’s Shura. Good news first: the yard is still here. I checked."],"rumor":["They say you got {n} cars out yesterday. Galya says {m}. Galya didn’t get out herself.","Yesterday: {n} cars. By the market it’s {m}. By lunch it’ll be a hundred. I’ll see to it.","I wrote {n} in my notebook. This morning it says {m}. Not my handwriting. Valerka’s.","My husband asked how many. I said {n}. He told Mityai — it became {m}. Men.","Yesterday {n}. The bench voted it up to {m}. I voted against. I was outvoted."],"later":["Later it is. I’m not going anywhere. I’ve been here since 1983.","Off you go. The news won’t go off — I put it in the fridge.","Fine. I’ll write it down: “Later”. There’s a column for that. My husband started it."]},"stage":{"up_en":["You’re in my notebook now. In pencil, for now — in case you’re just passing through.","Three days — I’ve switched to pen. You’re a resident now.","A week! You’re one of us. I can tell you where Galya parks her Oka. Sideways.","Two weeks. Yard committee! You get a vote. I get two — I’m in charge.","A month. You’re my right hand. No key to the building. But you know the intercom now — it’s me."]},"letter":{"ps":["P.S. I left you a sweet. It’s from last year, but sweets don’t go off. Neither do I.","P.S. I left you Tolik’s spare spanner. He hasn’t noticed yet.","P.S. I saved you a spot on the bench. I’m sitting on it so nobody takes it.","P.S. I left you half a pie from Auntie Valya. My husband tested the other half.","P.S. I left you a pass to the yard. It’s not valid, but it’s very pretty."]},"title":[["right","Right hand","I won’t give you the key to the building. But you know the intercom now — it’s me."],["night","Night watchman","The yard is yours at night and mine by day. Deal."],["clean","Not a scratch","Twenty yards, no crashes. I’ve nothing to report at the residents’ meeting — so I’ll report you."],["nohint","Did it myself","Twenty yards without hints. My husband can’t find his shoes without my hints."],["oka","Oka hunter","Tenth time you’ve moved the Oka. Galya thinks it’s personal. Let her."],["streak10","Unstoppable","Ten in a row. I turned my notebook over — thought I was writing on the wrong side."],["amb","Green corridor","You let the ambulance through ten times. Petrovna now only gets ill on your days."],["y100","A hundred","A hundred yards. Your page in my notebook ran out. Starting volume two."],["gift7","Favourite guest","Seventh gift. I keep a separate pocket in my apron now — yours."],["album10","Car buff","Ten cars in the album. My husband knows as many, but only by sound — and they all “knock”."]],"ntf":{"miss1":["The yard is jammed again. I didn’t let anyone in — they drove in themselves. Help!","Quiet without you today. Too quiet. Even my husband woke up to check.","Mikhalych: yard’s swept. You can fill it up — that’s what I swept it for."],"gift":["Your gift has been in my apron two days. The apron is starting to think it’s his.","Gift’s ready. My husband asked twice who it’s for. Twice I said — not you.","Gift’s on the bench. Mikhalych promised not to sweep it up before you come."],"daily":["Today’s yard is the same for everyone. Nobody has solved it yet. I told no one you’re coming.","Daily yard is ready. Tolik tried it. Said his steering wheel is on the wrong side.","Valerka: the daily is tough. I counted the moves twice. Got two answers."]},"bl":{"glasses":["Is that an Ikarus? Oh, it’s an Oka standing close. I forgot my glasses today.","Found my glasses! They were on my nose. My husband saw it all morning and said nothing.","Without glasses the yard looks empty. Lovely. Shame it isn’t."],"gai":["A whistle from the bushes! Officer, we’re letting our own out. Go and see Galya.","The officer wanted to fine us. I showed him forty years of my reports. He chose the bushes."]}}});